INSERT INTO `job_posting` (`id`, `title`, `standardized_title`, `level`, `department`, `company`, `location`, `experience`, `education`, `salary_min`, `salary_max`, `salary_months`, `headcount`, `responsibilities`, `requirements`, `jd_text`, `status`, `urgent`, `created_by`, `published_at`, `deleted_at`, `created_at`, `updated_at`) VALUES (3, '高级Java开发工程师', NULL, '高级', '研发中心 后台开发组', NULL, NULL, NULL, NULL, 20000, 35000, 14, 1, '[\"负责核心业务系统的架构设计与技术选型\", \"主导关键模块的编码实现与代码审查\", \"参与技术难点的攻关与性能优化\"]', '[\"精通 Java, SpringBoot, MySQL, Redis\", \"具备良好的系统设计能力和问题分析能力\"]', '', 'open', 0, 1, '2026-06-20 09:12:44', NULL, '2026-06-20 17:12:43', '2026-06-20 10:10:30'), (4, '高级java开发工程师', NULL, '高级', '研发中心 后端组', NULL, NULL, NULL, NULL, NULL, NULL, 12, 1, '[\"负责后端核心模块的设计、开发与维护，确保系统高性能与高可用\", \"参与系统架构设计，优化现有技术栈，推动技术迭代\", \"编写高质量代码，进行代码审查，保证代码规范与质量\", \"配合DevOps团队完成容器化部署与Kubernetes集群管理\", \"参与AI相关功能开发，结合LangChain4j实现智能服务\"]', '[\"熟练掌握Java及Spring Boot框架，具备扎实的编程基础\", \"熟悉Redis、MySQL等存储技术，有性能调优经验\", \"了解LangChain4j或类似LLM框架，有实际项目经验优先\", \"熟悉Docker和Kubernetes，具备容器化部署经验\", \"具备良好的沟通能力和团队协作精神，能独立解决问题\"]', '岗位名称：高级java开发工程师\n所属部门：研发中心 后端组\n岗位职责：负责后端核心模块的设计、开发与维护，确保系统高性能与高可用；参与系统架构设计，优化现有技术栈，推动技术迭代；编写高质量代码，进行代码审查，保证代码规范与质量；配合DevOps团队完成容器化部署与Kubernetes集群管理；参与AI相关功能开发，结合LangChain4j实现智能服务\n任职要求：熟练掌握Java及Spring Boot框架，具备扎实的编程基础；熟悉Redis、MySQL等存储技术，有性能调优经验；了解LangChain4j或类似LLM框架，有实际项目经验优先；熟悉Docker和Kubernetes，具备容器化部署经验；具备良好的沟通能力和团队协作精神，能独立解决问题', 'open', 0, 1, '2026-07-10 03:48:42', NULL, '2026-07-10 11:48:41', '2026-07-10 03:48:58');
