INSERT INTO `raw_job_record` (`id`, `source_document_id`, `title`, `standardized_title`, `company`, `city`, `salary_text`, `experience_text`, `education_text`, `jd_text`, `responsibilities`, `requirements`, `keywords`, `posted_at_text`, `crawled_at_text`, `dedup_status`, `normalized_data`, `created_at`) VALUES (2, 2, '高级系统架构师', '系统架构师', '科大讯飞', '江苏省·南京市', NULL, '五年以上开发经验', '本科及以上', '【工作职责】 1、技术引领与架构设计：主导项目整体架构设计，确保系统具备高度的稳定性、可扩展性与高性能；深入参与核心模块的开发，把控关键技术环节，保障项目技术方向的正确性。 2、团队管理与协作：带领技术团队开展研发工作，为团队成员提供技术指导与培训，提升团队整体技术能力；定期组织团队技术交流与培训，提升团队整体技术水平；协调团队与其他部门之间的沟通协作，确保项目顺利推进。 3、项目推进与质量保障：跟进项目状态，在项目实施过程中，带领团队攻克复杂技术难题，保证项目按时交付。识别并管控技术风险，制定有效的应对方案。 4、技术优化与创新：关注行业技术发展趋势，引入新技术、新方法，对现有系统进行性能优化与技术升级；参与技术预研，探索新技术在项目中的应用，为公司技术创新提供支持。 【任职资格】 1、大学本科及以上学历，五年以上开发经验，有大型项目的架构经验或作为核心成员开发过复杂的产品级的应用者优先； 2、精通各类技术，熟练掌握 Spring、Spring Boot、Spring Cloud 等主流Java框架；熟悉常用数据结构和设计模式，具备良好的面向对象编程和设计能力。同时具有C/C++、Go、Python语言研发经验者优先； 3、有架构设计和性能优化的经验，能够主导框架开发，制定合理有效的开发规范，搭建高效集成的开发环境，提高开发质量和效率； 4、深刻理解标准，对可用性、可访问性、项目模块化等相关知识有实际的了解和实践经验，确保开发的网页在各种浏览器和设备上都能正常显示和使用； 5、具备优秀的沟通能力，有团队管理经验（5人或以上团队），能够与团队成员、其他部门以及客户进行有效的沟通和协作。能够清晰地传达项目需求和技术方案，协调各方资源，解决项目中的问题。', '1、技术引领与架构设计：主导项目整体架构设计，确保系统具备高度的稳定性、可扩展性与高性能；深入参与核心模块的开发，把控关键技术环节，保障项目技术方向的正确性。 2、团队管理与协作：带领技术团队开展研发工作，为团队成员提供技术指导与培训，提升团队整体技术能力；定期组织团队技术交流与培训，提升团队整体技术水平；协调团队与其他部门之间的沟通协作，确保项目顺利推进。 3、项目推进与质量保障：跟进项目状态，在项目实施过程中，带领团队攻克复杂技术难题，保证项目按时交付。识别并管控技术风险，制定有效的应对方案。 4、技术优化与创新：关注行业技术发展趋势，引入新技术、新方法，对现有系统进行性能优化与技术升级；参与技术预研，探索新技术在项目中的应用，为公司技术创新提供支持。', '1、大学本科及以上学历，五年以上开发经验，有大型项目的架构经验或作为核心成员开发过复杂的产品级的应用者优先； 2、精通各类技术，熟练掌握 Spring、Spring Boot、Spring Cloud 等主流Java框架；熟悉常用数据结构和设计模式，具备良好的面向对象编程和设计能力。同时具有C/C++、Go、Python语言研发经验者优先； 3、有架构设计和性能优化的经验，能够主导框架开发，制定合理有效的开发规范，搭建高效集成的开发环境，提高开发质量和效率； 4、深刻理解标准，对可用性、可访问性、项目模块化等相关知识有实际的了解和实践经验，确保开发的网页在各种浏览器和设备上都能正常显示和使用； 5、具备优秀的沟通能力，有团队管理经验（5人或以上团队），能够与团队成员、其他部门以及客户进行有效的沟通和协作。能够清晰地传达项目需求和技术方案，协调各方资源，解决项目中的问题。', 'python, java', '2026-05-12T18:47:35', '2026-06-04T08:53:31.442Z', 'unique', '{\"source_file_schema\": \"job-v1\"}', '2026-06-20 18:10:18'), (3, 3, '中级软件开发工程师', '软件开发工程师', '科大讯飞', '安徽省·合肥市', NULL, '3年以上', NULL, '【工作职责】 【岗位职责】 1、保证系统的效率和可靠性以及代码质量和可维护性。 2、参与项目的需求分析和设计方案，制定软件开发方案； 3、编写软件开发大纲，按时完成需求分析，参与设计开发和测试工作，保证开发质量和效率； 4、参与系统对外接口的相关交流和开发工作； 5、参与编制用户手册等技术档案，参与系统实施工作。 6、能够配合项目经理编写售前方案和可研文档。 【任职资格】 【任职要求】 1、3年以上Java/C/C++等开发经验； 2、理解io、多线程、集合等基础框架,熟悉并发编程原理，对事务、锁、并发等实现机制有深入了解； 3、熟练使用Java/python/C++一项或多项语言开发，熟悉常用的设计模式， 4、熟悉postgresql、mysql等常用数据库，熟悉常用的分布式系统和中间件（包括不限于微服务，消息队列，调度系统，存储系统，NOSQL等），有相关开发经验； 5、熟练掌握Spring/SpringMVC/Spring Cloud、Tomcat、Netty、MyBatis等技术框架，熟练运用Nginx、Redis、ES、MQ、ZK、Kafka等企业中间件； 6、具备疑难问题定位排查，熟悉常用的内存分析，日志分析等工具命令。 7、熟悉使用Linux基本命令，了解CI/CD流程; 8、对JNI有基础了解和使用，了解docker容器及相关命令的使用。 9、主导或参与过项目的完整开发流程，熟悉项目开发迭代流程、熟悉代码开发规范，熟悉设计文档编写制定。 10、良好的沟通能力、团队合作精神；认真负责、具有高度责任感；能够主动发现问题并提出优化建议。 开发能力：具备基本功能的设计能力，熟悉平台开发流程，能够进行核心基础框架功能模块编写，能够完成业务能力建设。 沟通能力：具备良好的沟通表达能力，能够理解项目需求并转化为设计文档等平台开发建设的指导性文件。 学习能力：具备良好的自我驱动学习能力，能很快掌握一个新技术或者新工具的技术调研和使用。 项目经验：参与过项目的完整建设，熟悉项目开发的整个生命流程。', '【岗位职责】 1、保证系统的效率和可靠性以及代码质量和可维护性。 2、参与项目的需求分析和设计方案，制定软件开发方案； 3、编写软件开发大纲，按时完成需求分析，参与设计开发和测试工作，保证开发质量和效率； 4、参与系统对外接口的相关交流和开发工作； 5、参与编制用户手册等技术档案，参与系统实施工作。 6、能够配合项目经理编写售前方案和可研文档。', '【任职要求】 1、3年以上Java/C/C++等开发经验； 2、理解io、多线程、集合等基础框架,熟悉并发编程原理，对事务、锁、并发等实现机制有深入了解； 3、熟练使用Java/python/C++一项或多项语言开发，熟悉常用的设计模式， 4、熟悉postgresql、mysql等常用数据库，熟悉常用的分布式系统和中间件（包括不限于微服务，消息队列，调度系统，存储系统，NOSQL等），有相关开发经验； 5、熟练掌握Spring/SpringMVC/Spring Cloud、Tomcat、Netty、MyBatis等技术框架，熟练运用Nginx、Redis、ES、MQ、ZK、Kafka等企业中间件； 6、具备疑难问题定位排查，熟悉常用的内存分析，日志分析等工具命令。 7、熟悉使用Linux基本命令，了解CI/CD流程; 8、对JNI有基础了解和使用，了解docker容器及相关命令的使用。 9、主导或参与过项目的完整开发流程，熟悉项目开发迭代流程、熟悉代码开发规范，熟悉设计文档编写制定。 10、良好的沟通能力、团队合作精神；认真负责、具有高度责任感；能够主动发现问题并提出优化建议。 开发能力：具备基本功能的设计能力，熟悉平台开发流程，能够进行核心基础框架功能模块编写，能够完成业务能力建设。 沟通能力：具备良好的沟通表达能力，能够理解项目需求并转化为设计文档等平台开发建设的指导性文件。 学习能力：具备良好的自我驱动学习能力，能很快掌握一个新技术或者新工具的技术调研和使用。 项目经验：参与过项目的完整建设，熟悉项目开发的整个生命流程。', 'python, java', '2026-05-12T18:46:04', '2026-06-04T08:53:31.442Z', 'unique', '{\"source_file_schema\": \"job-v1\"}', '2026-06-20 18:10:19'), (4, 4, '中级研究算法工程师', '研究算法工程师', '科大讯飞', '安徽省·合肥市', NULL, '2年及以上相关经验', '硕士及以上', '【工作职责】 【岗位职责】 1、负责工业异音检测/声学异常检测算法的工程化实现、效果迭代与交付落地。 2、完成音频/振动信号的数据处理全流程：采集质量评估、清洗、分段、去噪/增强、特征构建，确保训练与推理一致性。 3、基于既定算法方案实现模型训练、推理与评估流程，支持产品化部署与现场验证。 4、针对复杂噪声与多工况变化，进行模型/阈值/特征参数调优，降低误报漏报、提升鲁棒性与稳定性。 5、参与数据闭环：协助制定标注规范、难例挖掘、误报漏报归因分析，推动算法快速迭代。 6、与硬件/产品/测试团队协作，定位现场问题并提出可执行的算法改进方案，沉淀可复用模块与文档。 【任职资格】 【任职要求】 1、硕士及以上学历，声学、信号处理、计算机、电子工程、自动化等相关专业。 2、具备扎实的信号处理基础，熟悉常见时域/频域/时频分析方法与声学特征构建思路。 3、具备机器学习/深度学习基础，理解分类、度量学习或异常检测的基本范式与评估方法。 4、熟练使用 Python 进行算法开发与验证；具备 MATLAB 或 C++ 能力者优先。 5、2 年及以上相关经验，有工业声音/异音检测/异常检测/设备故障诊断等落地经验优先。 6、工程意识强，能在真实数据与现场约束下推进算法上线与持续迭代。 【加分项】 1、有工业异音检测或声学质检完整交付经验（从数据到上线，能说清楚指标与闭环）。 2、有小样本/长尾/弱监督场景的异常检测经验（工业异常样本稀缺）。 3、有复杂噪声环境鲁棒性经验：抗噪、非平稳干扰抑制、背景噪声建模等。 4、有跨工况/跨设备泛化经验：域偏移处理、归一化策略、阈值体系设计等。 5、有实时/边缘侧推理或性能优化经验。 6、良好的沟通协作能力，能与硬件/测试一起快速定位问题并闭环。', '【岗位职责】 1、负责工业异音检测/声学异常检测算法的工程化实现、效果迭代与交付落地。 2、完成音频/振动信号的数据处理全流程：采集质量评估、清洗、分段、去噪/增强、特征构建，确保训练与推理一致性。 3、基于既定算法方案实现模型训练、推理与评估流程，支持产品化部署与现场验证。 4、针对复杂噪声与多工况变化，进行模型/阈值/特征参数调优，降低误报漏报、提升鲁棒性与稳定性。 5、参与数据闭环：协助制定标注规范、难例挖掘、误报漏报归因分析，推动算法快速迭代。 6、与硬件/产品/测试团队协作，定位现场问题并提出可执行的算法改进方案，沉淀可复用模块与文档。', '【任职要求】 1、硕士及以上学历，声学、信号处理、计算机、电子工程、自动化等相关专业。 2、具备扎实的信号处理基础，熟悉常见时域/频域/时频分析方法与声学特征构建思路。 3、具备机器学习/深度学习基础，理解分类、度量学习或异常检测的基本范式与评估方法。 4、熟练使用 Python 进行算法开发与验证；具备 MATLAB 或 C++ 能力者优先。 5、2 年及以上相关经验，有工业声音/异音检测/异常检测/设备故障诊断等落地经验优先。 6、工程意识强，能在真实数据与现场约束下推进算法上线与持续迭代。 【加分项】 1、有工业异音检测或声学质检完整交付经验（从数据到上线，能说清楚指标与闭环）。 2、有小样本/长尾/弱监督场景的异常检测经验（工业异常样本稀缺）。 3、有复杂噪声环境鲁棒性经验：抗噪、非平稳干扰抑制、背景噪声建模等。 4、有跨工况/跨设备泛化经验：域偏移处理、归一化策略、阈值体系设计等。 5、有实时/边缘侧推理或性能优化经验。 6、良好的沟通协作能力，能与硬件/测试一起快速定位问题并闭环。', 'python', '2026-05-12T18:46:04', '2026-06-04T08:53:31.442Z', 'unique', '{\"source_file_schema\": \"job-v1\"}', '2026-06-20 18:10:19'), (5, 5, '中级软件开发工程师', '软件开发工程师', '科大讯飞', '安徽省·合肥市', NULL, NULL, '本科', '【工作职责】 【岗位职责】 1.负责工业智能应用边缘侧核心产品设计和功能模块开发工作，包含设备接入管理、信号采集、信号预处理、边缘计算模型、数据通信接口等； 2.负责边缘计算设备运行时环境、SDK、核心应用以及相关工具及服务的设计、开发和优化； 3.负责边缘侧信号处理算法的实现和嵌入式优化。 【任职资格】 【任职要求】 1.自动化、电子、通信、计算机相关专业本科或以上学历； 2.具备扎实的计算机专业基础，理解操作系统、计算机体系结构、编程语言、网络、安全等基础技术的基本概念和原理； 3.精通C/C++编程语言，熟练使用Q-t编程，能够熟练使用bash 或者 python等脚本语言； 4.熟悉基于ARM的Linux嵌入式编程； 5.了解常见工业现场协议、物联网常见通信协议：如MQ-TT、Modbus、AMQP、OPC UA等协议； 6.具备Q-t应用开发经验，具备工业自动化软件开发经验。', '【岗位职责】 1.负责工业智能应用边缘侧核心产品设计和功能模块开发工作，包含设备接入管理、信号采集、信号预处理、边缘计算模型、数据通信接口等； 2.负责边缘计算设备运行时环境、SDK、核心应用以及相关工具及服务的设计、开发和优化； 3.负责边缘侧信号处理算法的实现和嵌入式优化。', '【任职要求】 1.自动化、电子、通信、计算机相关专业本科或以上学历； 2.具备扎实的计算机专业基础，理解操作系统、计算机体系结构、编程语言、网络、安全等基础技术的基本概念和原理； 3.精通C/C++编程语言，熟练使用Q-t编程，能够熟练使用bash 或者 python等脚本语言； 4.熟悉基于ARM的Linux嵌入式编程； 5.了解常见工业现场协议、物联网常见通信协议：如MQ-TT、Modbus、AMQP、OPC UA等协议； 6.具备Q-t应用开发经验，具备工业自动化软件开发经验。', 'python', '2026-05-12T18:46:04', '2026-06-04T08:53:31.442Z', 'unique', '{\"source_file_schema\": \"job-v1\"}', '2026-06-20 18:10:19'), (6, 6, '高级软件开发工程师', '软件开发工程师', '科大讯飞', '安徽省·合肥市', NULL, '5年以上', '本科及以上', '【工作职责】 【岗位职责】 1.产业研究与业务规划：深入分析工业领域（如轨道交通、汽车电子、机械制造等）的业务痛点与发展趋势，挖掘AI可赋能的高价值场景；制定业务战略及Roadmap，平衡短期交付与长期技术布局，确保产品与市场需求及公司战略契合； 2.产品及方案管理：把握AI驱动的工业解决方案设计。包含不限于工艺优化、质量管控、运营运维、供应链预测等；联合算法、工程团队设计技术方案，确保业务价值可量化、技术可行； 3.产品落地与项目管理：协调研发、算法、硬件团队推进产品开发，把控关键节点，确保产品按时交付；制定产品商业化策略，支持售前团队完成POC验证、客户交付与规模化推广； 4.跨部门协作与生态建设：与市场、销售团队协作，输出解决方案白皮书、案例集及演示工具；对接工业软件厂商、设备供应商及轨交行业合作伙伴，构建AI生态合作体系； 【任职资格】 【任职要求】 1.本科及以上学历，计算机、工业工程、自动化、轨道交通相关专业优先； 2.具有5年以上B端产品经验，具备轨交行业、工业AI产品或工业软件解决方案背景，具备轨交行业AI项目落地经验； 3.熟悉工业制造流程（研发、生产、供应链）或轨道交通典型场景； 4.具备较强的市场分析、需求抽象及商业化能力，能输出清晰的产品逻辑和商业模式； 5.熟悉AI技术框架（如机器学习、深度学习、计算机视觉），能与技术团队高效沟通； 6.具备出色的跨部门协作与项目管理能力，适应快节奏的工业客户需求响应； 7.以结果导向，注重产品实际落地效果而非单纯技术指标。 【加分项】 熟悉工业物联网（IIoT）、边缘计算、云边端协同架构。 具备项目管理认证（PMP/NPDP）或技术背景（Python/SQL）。', '【岗位职责】 1.产业研究与业务规划：深入分析工业领域（如轨道交通、汽车电子、机械制造等）的业务痛点与发展趋势，挖掘AI可赋能的高价值场景；制定业务战略及Roadmap，平衡短期交付与长期技术布局，确保产品与市场需求及公司战略契合； 2.产品及方案管理：把握AI驱动的工业解决方案设计。包含不限于工艺优化、质量管控、运营运维、供应链预测等；联合算法、工程团队设计技术方案，确保业务价值可量化、技术可行； 3.产品落地与项目管理：协调研发、算法、硬件团队推进产品开发，把控关键节点，确保产品按时交付；制定产品商业化策略，支持售前团队完成POC验证、客户交付与规模化推广； 4.跨部门协作与生态建设：与市场、销售团队协作，输出解决方案白皮书、案例集及演示工具；对接工业软件厂商、设备供应商及轨交行业合作伙伴，构建AI生态合作体系；', '【任职要求】 1.本科及以上学历，计算机、工业工程、自动化、轨道交通相关专业优先； 2.具有5年以上B端产品经验，具备轨交行业、工业AI产品或工业软件解决方案背景，具备轨交行业AI项目落地经验； 3.熟悉工业制造流程（研发、生产、供应链）或轨道交通典型场景； 4.具备较强的市场分析、需求抽象及商业化能力，能输出清晰的产品逻辑和商业模式； 5.熟悉AI技术框架（如机器学习、深度学习、计算机视觉），能与技术团队高效沟通； 6.具备出色的跨部门协作与项目管理能力，适应快节奏的工业客户需求响应； 7.以结果导向，注重产品实际落地效果而非单纯技术指标。 【加分项】 熟悉工业物联网（IIoT）、边缘计算、云边端协同架构。 具备项目管理认证（PMP/NPDP）或技术背景（Python/SQL）。', 'python', '2026-05-12T18:46:04', '2026-06-04T08:53:31.442Z', 'unique', '{\"source_file_schema\": \"job-v1\"}', '2026-06-20 18:10:19'), (7, 7, '高级研究算法工程师', '研究算法工程师', '科大讯飞', '安徽省·合肥市', NULL, '5年以上相关', '博士学历', '【工作职责】 【岗位职责】 1、负责声纹识别/声学异常识别方向的前沿算法研发与技术路线规划，覆盖：异音检测、声纹建模、异常检测、故障诊断与趋势预测等。 2、结合声学/振动机理与数据驱动方法，构建可解释、可泛化、可落地的算法体系（机理 + 统计学习/深度学习融合）。 3、牵头核心算法攻关：复杂噪声场下的鲁棒性、弱异常与早期故障识别、跨设备/跨工况域泛化、样本稀缺与长尾问题等。 4、设计高质量的特征与表征学习方案：时域/频域/时频域特征、嵌入表示（embedding）、度量学习/对比学习等。 【任职资格】 【任职要求】 1、博士学历（声学/信号处理/机器学习相关方向），有声纹识别、异常检测、故障诊断等方向的理论研究或成果；或 硕士及以上学历 + 5 年以上相关领域经验，具备独立主导算法方向的能力。 2、扎实的数学与信号处理基础，理解声学/振动信号生成机理、传播与噪声干扰机制，能做建模与解释。 3、精通声学信号分析与建模方法：STFT/小波/倒谱、包络分析、谱峰/谐波结构、阶次相关思想等。 4、在声纹识别/音频表征学习/异常检测至少一个方向有深入积累：能提出先进方案并显著提升关键指标。 5、熟练使用 Python / MATLAB 进行算法验证、实现与优化。 【加分项】 1、工业设备状态监测 / 预测性维护公司或团队：做过旋转机械（电机/泵/风机/压缩机/轴承/齿轮箱）相关的异常检测、诊断或趋势预测。 2、有声纹识别相关先进方法经验：度量学习、对比学习、自监督/半监督、少样本学习等。 3、有复杂噪声/混响/非平稳干扰下的鲁棒识别经验（抗噪、去混响、源分离等思路或工程实践）。 4、有早期故障识别、弱异常检测、趋势预测或 RUL（剩余寿命）相关经验。 5、有论文/专利/开源成果，或在顶会期刊（语音/信号处理/机器学习）发表过工作。 6、参与过DCASE Challenge，在国内声学/音频信号处理会议（中国声学学会的全国声学大会、声频工程学术交流年会）有过工业声纹处理研究与应用论文贡献者优先 6、具备良好的技术判断、问题拆解、跨团队推进能力，能把研究型算法落到工程指标上。', '【岗位职责】 1、负责声纹识别/声学异常识别方向的前沿算法研发与技术路线规划，覆盖：异音检测、声纹建模、异常检测、故障诊断与趋势预测等。 2、结合声学/振动机理与数据驱动方法，构建可解释、可泛化、可落地的算法体系（机理 + 统计学习/深度学习融合）。 3、牵头核心算法攻关：复杂噪声场下的鲁棒性、弱异常与早期故障识别、跨设备/跨工况域泛化、样本稀缺与长尾问题等。 4、设计高质量的特征与表征学习方案：时域/频域/时频域特征、嵌入表示（embedding）、度量学习/对比学习等。', '【任职要求】 1、博士学历（声学/信号处理/机器学习相关方向），有声纹识别、异常检测、故障诊断等方向的理论研究或成果；或 硕士及以上学历 + 5 年以上相关领域经验，具备独立主导算法方向的能力。 2、扎实的数学与信号处理基础，理解声学/振动信号生成机理、传播与噪声干扰机制，能做建模与解释。 3、精通声学信号分析与建模方法：STFT/小波/倒谱、包络分析、谱峰/谐波结构、阶次相关思想等。 4、在声纹识别/音频表征学习/异常检测至少一个方向有深入积累：能提出先进方案并显著提升关键指标。 5、熟练使用 Python / MATLAB 进行算法验证、实现与优化。 【加分项】 1、工业设备状态监测 / 预测性维护公司或团队：做过旋转机械（电机/泵/风机/压缩机/轴承/齿轮箱）相关的异常检测、诊断或趋势预测。 2、有声纹识别相关先进方法经验：度量学习、对比学习、自监督/半监督、少样本学习等。 3、有复杂噪声/混响/非平稳干扰下的鲁棒识别经验（抗噪、去混响、源分离等思路或工程实践）。 4、有早期故障识别、弱异常检测、趋势预测或 RUL（剩余寿命）相关经验。 5、有论文/专利/开源成果，或在顶会期刊（语音/信号处理/