INSERT INTO `source_document` (`id`, `source`, `external_id`, `url`, `title`, `company`, `content_fingerprint`, `content_summary`, `source_meta`, `created_at`) VALUES (2, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=0dcf1873-7de3-4fa3-92c7-650b64358e09', '高级系统架构师', '科大讯飞', 'ea7f0c8507abced4e6bf89d48fd40bf2e0644bcc81b4824096e853c398286501', '【工作职责】 1、技术引领与架构设计：主导项目整体架构设计，确保系统具备高度的稳定性、可扩展性与高性能；深入参与核心模块的开发，把控关键技术环节，保障项目技术方向的正确性。 2、团队管理与协作：带领技术团队开展研发工作，为团队成员提供技术指导与培训，提升团队整体技术能力；定期组织团队技术交流与培训，提升团队整体技术水平；协调团队与其他部门之间的沟通协作，确保项目顺利推进。 3、项目推进与质量保障：跟进项目状态，在项目实施过程中，带领团队攻克复杂技术难题，保证项目按时交付。识别并管控技术风险，制定有效的应对方案。 4、技术优化与创新：关注行业技术发展趋势，引入新技术、新方法，对现有系统进行性能优化与技术升级；参与技术预研，探索新技术在项目中的应用，为公司技术创新提供支持。 【任职资格】 1、大学本科及以上学历，五年以上开发经验，有大型项目的架构经验或作为核心成员开发过复杂的产品级的应用者优先； 2、精通各类技术，熟练掌握 Spring、Spring Boot、Spring Cloud 等主流Java框架；熟悉常用数据结构和设计模式，具备良好的面向对象编程和设计能力。同时具有C/C++、Go、Python语言研发经验者优先； 3、有架构设计和性能优化的经验，能够主导框架开发，制定合理有效的开发规范，搭建高效集成的开发环境，提高开发质量和效率； 4、深刻理解标准，对可用性、可访问性、项目模块化等相关知识有实际的了解和实践经验，确保开发的网页在各种浏览器和设备上都能正常显示和使用； 5、具备优秀的沟通能力，有团队管理经验（5人或以上团队），能够与团队成员、其他部门以及客户进行有效的沟通和协作。能够清晰地传达项目需求和技术方案，协调各方资源，解决项目中的问题。', '{\"posted_at\": \"2026-05-12T18:47:35\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:18'), (3, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=b8b47ffc-31cb-453c-a653-2e5f3fa4fbe0', '中级软件开发工程师', '科大讯飞', 'da8ce5f6954c9426aaf8ce5f7b87fa552418e82639c7f70639d77a229a426cf8', '【工作职责】 【岗位职责】 1、保证系统的效率和可靠性以及代码质量和可维护性。 2、参与项目的需求分析和设计方案，制定软件开发方案； 3、编写软件开发大纲，按时完成需求分析，参与设计开发和测试工作，保证开发质量和效率； 4、参与系统对外接口的相关交流和开发工作； 5、参与编制用户手册等技术档案，参与系统实施工作。 6、能够配合项目经理编写售前方案和可研文档。 【任职资格】 【任职要求】 1、3年以上Java/C/C++等开发经验； 2、理解io、多线程、集合等基础框架,熟悉并发编程原理，对事务、锁、并发等实现机制有深入了解； 3、熟练使用Java/python/C++一项或多项语言开发，熟悉常用的设计模式， 4、熟悉postgresql、mysql等常用数据库，熟悉常用的分布式系统和中间件（包括不限于微服务，消息队列，调度系统，存储系统，NOSQL等），有相关开发经验； 5、熟练掌握Spring/SpringMVC/Spring Cloud、Tomcat、Netty、MyBatis等技术框架，熟练运用Nginx、Redis、ES、MQ、ZK、Kafka等企业中间件； 6、具备疑难问题定位排查，熟悉常用的内存分析，日志分析等工具命令。 7、熟悉使用Linux基本命令，了解CI/CD流程; 8、对JNI有基础了解和使用，了解docker容器及相关命令的使用。 9、主导或参与过项目的完整开发流程，熟悉项目开发迭代流程、熟悉代码开发规范，熟悉设计文档编写制定。 10、良好的沟通能力、团队合作精神；认真负责、具有高度责任感；能够主动发现问题并提出优化建议。 开发能力：具备基本功能的设计能力，熟悉平台开发流程，能够进行核心基础框架功能模块编写，能够完成业务能力建设。 沟通能力：具备良好的沟通表达能力，能够理解项目需求并转化为设计文档等平台开发建设的指导性文件。 学习能力：具备良好的自我驱动学习能力，能很快掌握一个新技术或者新工具的技术调研和使用。 项目经验：参与过项目的完整建设，熟悉项目开发的整个生命流程。', '{\"posted_at\": \"2026-05-12T18:46:04\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (4, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=48e46282-9ccb-4297-b0be-fa143483d390', '中级研究算法工程师', '科大讯飞', '75d90e3cc53169c447d72a2fbc7cd3c521e71166a433656fcce6904df3bfc98a', '【工作职责】 【岗位职责】 1、负责工业异音检测/声学异常检测算法的工程化实现、效果迭代与交付落地。 2、完成音频/振动信号的数据处理全流程：采集质量评估、清洗、分段、去噪/增强、特征构建，确保训练与推理一致性。 3、基于既定算法方案实现模型训练、推理与评估流程，支持产品化部署与现场验证。 4、针对复杂噪声与多工况变化，进行模型/阈值/特征参数调优，降低误报漏报、提升鲁棒性与稳定性。 5、参与数据闭环：协助制定标注规范、难例挖掘、误报漏报归因分析，推动算法快速迭代。 6、与硬件/产品/测试团队协作，定位现场问题并提出可执行的算法改进方案，沉淀可复用模块与文档。 【任职资格】 【任职要求】 1、硕士及以上学历，声学、信号处理、计算机、电子工程、自动化等相关专业。 2、具备扎实的信号处理基础，熟悉常见时域/频域/时频分析方法与声学特征构建思路。 3、具备机器学习/深度学习基础，理解分类、度量学习或异常检测的基本范式与评估方法。 4、熟练使用 Python 进行算法开发与验证；具备 MATLAB 或 C++ 能力者优先。 5、2 年及以上相关经验，有工业声音/异音检测/异常检测/设备故障诊断等落地经验优先。 6、工程意识强，能在真实数据与现场约束下推进算法上线与持续迭代。 【加分项】 1、有工业异音检测或声学质检完整交付经验（从数据到上线，能说清楚指标与闭环）。 2、有小样本/长尾/弱监督场景的异常检测经验（工业异常样本稀缺）。 3、有复杂噪声环境鲁棒性经验：抗噪、非平稳干扰抑制、背景噪声建模等。 4、有跨工况/跨设备泛化经验：域偏移处理、归一化策略、阈值体系设计等。 5、有实时/边缘侧推理或性能优化经验。 6、良好的沟通协作能力，能与硬件/测试一起快速定位问题并闭环。', '{\"posted_at\": \"2026-05-12T18:46:04\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (5, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=c2375e93-a154-4717-a402-7f4e8ab5bb5c', '中级软件开发工程师', '科大讯飞', '59fb7d8c54dd5314c431b0bafa24608790c5088bbe9d7586bf5caec155de267b', '【工作职责】 【岗位职责】 1.负责工业智能应用边缘侧核心产品设计和功能模块开发工作，包含设备接入管理、信号采集、信号预处理、边缘计算模型、数据通信接口等； 2.负责边缘计算设备运行时环境、SDK、核心应用以及相关工具及服务的设计、开发和优化； 3.负责边缘侧信号处理算法的实现和嵌入式优化。 【任职资格】 【任职要求】 1.自动化、电子、通信、计算机相关专业本科或以上学历； 2.具备扎实的计算机专业基础，理解操作系统、计算机体系结构、编程语言、网络、安全等基础技术的基本概念和原理； 3.精通C/C++编程语言，熟练使用Q-t编程，能够熟练使用bash 或者 python等脚本语言； 4.熟悉基于ARM的Linux嵌入式编程； 5.了解常见工业现场协议、物联网常见通信协议：如MQ-TT、Modbus、AMQP、OPC UA等协议； 6.具备Q-t应用开发经验，具备工业自动化软件开发经验。', '{\"posted_at\": \"2026-05-12T18:46:04\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (6, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=62f3f158-becf-4abf-a37c-adc130dd3158', '高级软件开发工程师', '科大讯飞', '0d6985f832620408791df0a1a80f5d3e554b9e2e9e4d466fbc6ce355e1e0457e', '【工作职责】 【岗位职责】 1.产业研究与业务规划：深入分析工业领域（如轨道交通、汽车电子、机械制造等）的业务痛点与发展趋势，挖掘AI可赋能的高价值场景；制定业务战略及Roadmap，平衡短期交付与长期技术布局，确保产品与市场需求及公司战略契合； 2.产品及方案管理：把握AI驱动的工业解决方案设计。包含不限于工艺优化、质量管控、运营运维、供应链预测等；联合算法、工程团队设计技术方案，确保业务价值可量化、技术可行； 3.产品落地与项目管理：协调研发、算法、硬件团队推进产品开发，把控关键节点，确保产品按时交付；制定产品商业化策略，支持售前团队完成POC验证、客户交付与规模化推广； 4.跨部门协作与生态建设：与市场、销售团队协作，输出解决方案白皮书、案例集及演示工具；对接工业软件厂商、设备供应商及轨交行业合作伙伴，构建AI生态合作体系； 【任职资格】 【任职要求】 1.本科及以上学历，计算机、工业工程、自动化、轨道交通相关专业优先； 2.具有5年以上B端产品经验，具备轨交行业、工业AI产品或工业软件解决方案背景，具备轨交行业AI项目落地经验； 3.熟悉工业制造流程（研发、生产、供应链）或轨道交通典型场景； 4.具备较强的市场分析、需求抽象及商业化能力，能输出清晰的产品逻辑和商业模式； 5.熟悉AI技术框架（如机器学习、深度学习、计算机视觉），能与技术团队高效沟通； 6.具备出色的跨部门协作与项目管理能力，适应快节奏的工业客户需求响应； 7.以结果导向，注重产品实际落地效果而非单纯技术指标。 【加分项】 熟悉工业物联网（IIoT）、边缘计算、云边端协同架构。 具备项目管理认证（PMP/NPDP）或技术背景（Python/SQL）。', '{\"posted_at\": \"2026-05-12T18:46:04\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (7, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=d0825525-5d24-48b0-87fc-5e941ab0a3c4', '高级研究算法工程师', '科大讯飞', '0a782ee25fe6103b36f52531366998774788a9fe2777c60b95205731651d01af', '【工作职责】 【岗位职责】 1、负责声纹识别/声学异常识别方向的前沿算法研发与技术路线规划，覆盖：异音检测、声纹建模、异常检测、故障诊断与趋势预测等。 2、结合声学/振动机理与数据驱动方法，构建可解释、可泛化、可落地的算法体系（机理 + 统计学习/深度学习融合）。 3、牵头核心算法攻关：复杂噪声场下的鲁棒性、弱异常与早期故障识别、跨设备/跨工况域泛化、样本稀缺与长尾问题等。 4、设计高质量的特征与表征学习方案：时域/频域/时频域特征、嵌入表示（embedding）、度量学习/对比学习等。 【任职资格】 【任职要求】 1、博士学历（声学/信号处理/机器学习相关方向），有声纹识别、异常检测、故障诊断等方向的理论研究或成果；或 硕士及以上学历 + 5 年以上相关领域经验，具备独立主导算法方向的能力。 2、扎实的数学与信号处理基础，理解声学/振动信号生成机理、传播与噪声干扰机制，能做建模与解释。 3、精通声学信号分析与建模方法：STFT/小波/倒谱、包络分析、谱峰/谐波结构、阶次相关思想等。 4、在声纹识别/音频表征学习/异常检测至少一个方向有深入积累：能提出先进方案并显著提升关键指标。 5、熟练使用 Python / MATLAB 进行算法验证、实现与优化。 【加分项】 1、工业设备状态监测 / 预测性维护公司或团队：做过旋转机械（电机/泵/风机/压缩机/轴承/齿轮箱）相关的异常检测、诊断或趋势预测。 2、有声纹识别相关先进方法经验：度量学习、对比学习、自监督/半监督、少样本学习等。 3、有复杂噪声/混响/非平稳干扰下的鲁棒识别经验（抗噪、去混响、源分离等思路或工程实践）。 4、有早期故障识别、弱异常检测、趋势预测或 RUL（剩余寿命）相关经验。 5、有论文/专利/开源成果，或在顶会期刊（语音/信号处理/机器学习）发表过工作。 6、参与过DCASE Challenge，在国内声学/音频信号处理会议（中国声学学会的全国声学大会、声频工程学术交流年会）有过工业声纹处理研究与应用论文贡献者优先 6、具备良好的技术判断、问题拆解、跨团队推进能力，能把研究型算法落到工程指标上。', '{\"posted_at\": \"2026-05-12T18:46:04\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (8, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=e47dcaa5-6fe5-48d6-8ed0-26d0ef1adb87', '高级系统架构师-大数据-JAVA', '科大讯飞', 'f53e31ad4f9bbc261847ddb8fa6e50a09b9522b0798b409681a62f98ae6a9e4e', '【工作职责】 1、负责业务系统与技术平台的整体架构设计、规划与持续演进，保障系统高性能、高可用与可扩展性。 2、主导核心系统与复杂业务模块的架构评审、技术方案设计与关键代码审查，确保架构落地符合规划。 3、深入理解业务需求，参与产品与研发方案讨论，从架构层面提供前瞻性建议与可行性分析。 4、攻克系统高并发、高可靠、分布式等领域的技术难题，制定技术规范与架构标准，推动研发效能提升。 5、跟踪业界技术趋势，引入适合的架构模式、中间件或工具，推动技术架构持续优化与团队技术成长。 【任职资格】 1、计算机或相关专业本科以上学历，8年以上后端开发经验，3年以上大型分布式系统架构设计经验。 2、精通Java/Go/Python等至少一门语言，熟悉JVM、多线程、网络编程，掌握常用设计模式与架构范式。 3、深刻理解微服务、云原生、容器化、消息队列、缓存、数据库等核心技术，具备高并发系统设计与调优经验。 4、熟悉主流云计算平台及相关服务，具备系统性能监控、容量规划与稳定性保障经验。 5、具备优秀的逻辑思维、系统分析与解决问题能力，能够主导复杂技术讨论并清晰输出架构决策。 6、、具备良好的沟通协调、团队合作与推动能力，责任心强，有技术热情，能带领团队完成技术落地与迭代。', '{\"posted_at\": \"2026-05-12T18:43:42\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (9, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=92b47445-7d86-42f6-a4f6-eb5d3c01b1a9', '中级软件开发工程师', '科大讯飞', 'c98cea0dc26d83ecdbfe48dfac49be731a7ed3355a7ec1857bb3e84d0cb4717c', '【工作职责】 1、【智能体开发】深入理解产品需求，可协同研发人员在低代码场景完成智能体工作流开发，并可持续优化智能体； 2、【智能体自测】基于开发的智能体构建智能体自测用例并完成自测和优化 3、【prompt设计】同时设计相关的意图分类和提示词，以满足产品和业务要求；通过意图体系设计和提示词优化，保证意图分类和内容输出的准确性，使得llm模型回答满足业务场景要求； 4、【prompt优化】设计和优化prompt的结构，使得prompt结构更灵活，更通用；优化prompt，使得prompt输出内容遵守伦理、法律法规以及安全性的要求，提升llm输出内容符合相关规定 5、【prompt测试】基于prompt的结构以及业务需求，构造满足业务要求的数据集 【任职资格】 1、教育背景 ：本科及以上学历，计算机、数学、统计学、人工智能等相关专业 2、核心能力（重点要求） - 具有一定的python开发能力，能够编写简单的脚本需求 - 熟悉大模型在 B 端的应用场景，逻辑清晰、善于总结归纳与抽象 - 深入了解 AI Agent，熟练使用 Coze、Dify 等智能体开发工具，能独立搭建复杂智能体 - 系统掌握 Prompt 工程方法，能够基于不同业务场景完成 Prompt 设计与效果评测 - 优秀的业务模型分析能力、沟通能力和文档编写能力 - 思路清晰、认真严谨，执行力强、自驱力高 - 对业务敏锐，能够在复杂环境中识别关键矛盾并制定短期与长远方案', '{\"posted_at\": \"2026-05-12T18:41:56\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (10, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=1c7e7699-dfe5-4ba8-aed8-bf0d189b1c41', '中级研究算法工程师', '科大讯飞', 'e1f39de4f70fcb5aa2993101d5ddcf00e32553cd31efc6a1965687cef100ed17', '【工作职责】 1. 主要从事自然语言处理相关的工作，服务汽车业务； 2. 负责NLP算法及大模型落地汽车人机交互的训练及优化； 3. 负责汽车相关的人机对话系统核心算法引擎开发； 4. 负责汽车人机交互核心算法落地的内存和性能优化工作。 【任职资格】 1. 统招本科及以上学历，计算机、通信、信号处理等相关专业。至少具备2年以上实际项目研发经验； 2. 熟练使用C++，有C++项目开发经验，并掌握基本shell脚本、Python等脚本语言； 3. 优秀的沟通协作和执行能力，并拥有强烈的责任心； 4. 优秀的分析和解决问题的能力，对挑战性问题充满激情； 5. 掌握常用的机器学习算法、语音识别、自然语言处理等相关算法优先。', '{\"posted_at\": \"2026-05-12T18:41:56\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (11, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=740f7bad-9562-44a3-b2b7-336b12fc86ed', '高级系统测试工程师', '科大讯飞', '9fa51ac1196817359a336343d167f88b6b38425d1e029b31da27b6817e7c11c4', '【工作职责】 1.根据需求等相关文档分析测试需求，设计、编写、优化测试用例； 2.选择合理的测试执行策略，根据不同项目阶段选择不同测试用例进行执行及结果跟踪 3.总结、反馈、优化测试及项目过程；并协助项目、研发、产品进行项目过程问题改进及优化 4.和项目内部相关干系人保持良好沟通，协调项目与测试内部资源，做好资源协调工作 5.与项目外相关干系人保持良好沟通，协助推进效果、信源、供应商问题定位、解决、验证闭环 6.与客户保持良好的沟通及测试对接，完成客户的测试需求，协助项目过程顺利推动 7.与其他项目测试组保持良好沟通，相互学习优秀经验、借鉴优秀成果，推动测试内部共同提升 8.可根据业务线重点目标分解测试目标，做好计划及跟踪 【任职资格】 1、本科及以上学历，至少5年以上汽车生态软件（含语音助理）测试经验，至少2个以上项目测试管理经验。 2、熟练掌握测试理论、测试方法；能够快速理解需求、设计测试方案。 3、熟悉车载AI能力（如语音唤醒、识别、大模型等）产品测试 4、精通车载类项目流程及测试流程，能够与产品、设计、研发、质量等相关人员保持良好流程对接，发现可优化流程并改进； 5、熟练掌握Android等车机平台终端命令，能够完成Android等车机系统平台测试环境搭建； 6、有一定脚本编写能力，精通一个以上的编程语言（C++,JAVA,python)优先 7、能够接受因项目需求的出差工作', '{\"posted_at\": \"2026-05-12T18:41:56\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (12, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=3a5a06e8-cdc6-485d-b68f-a354c0738bb7', '中级用户研究工程师', '科大讯飞', '4cbab608987044a9a2b1d339e242c60fb0964efe9b6e740ec806005e96d0a2dd', '【工作职责】 1、负责搭建整体的体验评价体系，在设计流程中的不同节点引入合适的体验评价方法，协同设计师推动体验迭代，有UEQ的经验者优先 2、通过对数据的敏锐洞察以及定性和定量分析，迅速定位业务问题、发现潜在机会，独立编写分析报告，并提出可落地方案；能够独立完成关键项目的体验评价，并输出体验评价报告 3、负责收集行业市场动态信息，把握行业发展趋势，梳理主要竞争对手的动作策略，定期输出市场分析报告。对用户诉求和行业趋势敏锐，能够梳理出前瞻用户洞见、趋势洞见、行业洞见，为设计指引方向； 4、跨团队协同，分享研究成果，主动推进研究转化落地，在部门层面提升有效性和影响力 【任职资格】 1、心理学、社会学、统计学、传播学、人机交互、计算机等专业背景。拥有数据商业分析相关经验，有解决商业问题的成功经历，有汽车行业或品牌经验者优先；汽车、出行或互联网相关从业背景。 2、有完整的研究产出及可度量成果。思维系统、严谨，具备优秀的分析与洞察能力 3、 具有良好的逻辑思维和分析能力，能熟练利用Excel、Power BI、Fine BI等进行数据分析，搭建数据模型，熟悉SQL、Python等优先； 4、业务敏感度强，学习能力和创新能力强，具备较强的表达沟通能力和团队合作意识，能够简明、清晰地向各个角色传达研究成果，推动研究落地，积极主动构建用户中心的团队文化', '{\"posted_at\": \"2026-05-12T18:41:56\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (13, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=473245a8-c281-4aec-8d40-4a626773fb48', '高级用户研究工程师', '科大讯飞', '837fa7efb29dfbd55f12594cfec880cebc068dde6022f5bfae1ae4744aba6f89', '【工作职责】 1、负责搭建整体的体验评价体系，在设计流程中的不同节点引入合适的体验评价方法，协同设计师推动体验迭代，有UEQ的经验者优先 2、通过对数据的敏锐洞察以及定性和定量分析，迅速定位业务问题、发现潜在机会，独立编写分析报告，并提出可落地方案；能够独立完成关键项目的体验评价，并输出体验评价报告 3、负责收集行业市场动态信息，把握行业发展趋势，梳理主要竞争对手的动作策略，定期输出市场分析报告。对用户诉求和行业趋势敏锐，能够梳理出前瞻用户洞见、趋势洞见、行业洞见，为设计指引方向； 4、跨团队协同，分享研究成果，主动推进研究转化落地，在部门层面提升有效性和影响力 【任职资格】 1、心理学、社会学、统计学、传播学、人机交互、计算机等专业背景。拥有数据商业分析相关经验，有解决商业问题的成功经历，有汽车行业或品牌经验者优先；汽车、出行或互联网相关从业背景。 2、有完整的研究产出及可度量成果。思维系统、严谨，具备优秀的分析与洞察能力 3、 具有良好的逻辑思维和分析能力，能熟练利用Excel、Power BI、Fine BI等进行数据分析，搭建数据模型，熟悉SQL、Python等优先； 4、业务敏感度强，学习能力和创新能力强，具备较强的表达沟通能力和团队合作意识，能够简明、清晰地向各个角色传达研究成果，推动研究落地，积极主动构建用户中心的团队文化', '{\"posted_at\": \"2026-05-12T18:41:56\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (14, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=7b536360-dc02-42d3-89b7-5370e47aaa0c', '中级研究算法-多模态交互研究员', '科大讯飞', '57bec9eaf37c5d4d874a9246d72ceaeaa75a93a89335c88ec59b7d5f3650dcce', '【工作职责】 负责多模态人机交互算法的研发以及在家庭机器人场景的落地。 【任职资格】 1、对多模态人机交互有浓厚的兴趣，喜欢做落地型的研究。 2、硕士及以上学历，计算机、人工智能、大数据等相关专业优先。 3、熟练掌握Python/C++等计算机编程，具有PyTorch编程经验的优先。 4、具有大语言模型、语音、计算机视觉等方向的算法研发和落地经验； 5、具有语音交互或多模态交互方面的算法研发和落地经验的优先。', '{\"posted_at\": \"2026-05-12T18:41:07\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (15, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=871bc360-a202-4927-be62-dba829122065', '高级系统架构师', '科大讯飞', '7185c27e9c8069542e8d994ba18e264161a0d7a4fd9b6a3d3633aaa3ac7cb438', '【工作职责】 - 负责家庭机器人应用侧整体后端架构设计与演进，设计高可扩展、高可用、可持续演进的系统结构 - 构建AI能力（大模型、多模态、语音等）与业务系统的融合架构，推动AI能力在真实业务场景中的可控、可观测、可优化落地 - 建设可观测体系（日志/监控/告警/追踪），推动CI/CD与自动化测试体系 - 对关键技术决策负责，影响并提升团队整体技术水准，在复杂问题中承担责任，推动问题闭环解决 【任职资格】 1、基础能力 - 5年以上后端开发经验，2年以上架构设计经验 - 熟悉主流后端技术栈（Java / Go / Python 至少精通一种） - 扎实的分布式系统设计能力 - 熟悉微服务、服务治理、消息队列、缓存体系、数据库设计 - 对系统稳定性、扩展性、安全性有成熟认知 2、架构能力 - 能从0到1设计复杂系统架构 - 有大规模系统性能优化经验 - 熟悉高并发场景设计 - 有多系统协同架构设计经验 3、AI工程认知 - 对大模型工程化有实践经验或强认知 - 熟悉Prompt工程、Agent框架或LLM系统接入架构 - 熟练使用AI提效工具（如 CC、OpenClaw 或类似工具） - 能将AI工具深度融入研发流程 4、个人特质 - 责任心强，结果导向 - 自驱力高，不等任务驱动 - 有长期主义视角，愿意参与产品共同成长 - 能在不确定环境中持续推进事情 5、加分项 - 有智能硬件或机器人相关项目经验 - 有多模态系统架构经验 - 有语音交互或实时系统经验 - 有平台化能力建设经验 - 有从0到1创业或核心骨干经历', '{\"posted_at\": \"2026-05-12T18:41:07\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (16, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=7f4b9b56-79b0-4de1-a40b-0289dc0b089d', 'AI研究院-中级Agent开发工程师', '科大讯飞', '3a84577628e1131891f6d6d529c2a501fe4cc4df0abe5337a2f11a530fe98241', '【工作职责】 1. 大模型应用平台架构和应用方案的设计 - 参与大模型应用平台的整体架构设计与技术选型，构建高可用、可扩展的AI系统。 - 设计支持多模态、多任务的大模型服务框架，优化模型推理、部署及资源调度方案。 - 大模型应用和解决方案的需求分析，方案设计和研发。 2. 系统研发与功能开发 - 负责大模型应用平台核心模块开发，包括数据处理、模型训练/推理加速、分布式任务调度等。 - 开发模型服务化接口（如RESTful API）、Prompt工程工具链、模型监控与评估系统。 - 实现大模型与业务场景的深度集成，如对话系统、知识问答、代码生成等应用功能。 3. 性能优化与工程化 - 解决大模型训练与推理中的性能瓶颈，优化GPU资源利用率及计算效率。 - 研究模型压缩、量化、蒸馏等技术，降低部署成本并提升推理速度。 - 保障平台的高并发、低延迟与稳定性，设计容灾和自动化运维方案。 【任职资格】 1. 基础要求 - 计算机科学、人工智能、数学等相关专业硕士及以上学历（优秀本科生可放宽）。 - 3年以上AI系统开发经验，1年以上大模型相关项目经验。 2. 技术能力 - 精通Python，熟悉C++/Go/Java中至少一门语言，掌握PyTorch/TensorFlow框架。 - 有LangChain、LlamaIndex等大模型应用框架开发经验者优先。 - 熟悉Agent技术栈、RAG（检索增强生成）或复杂系统架构设计者优先。 -有大模型应用相关开发经验优先 4. - 强烈的技术热情，优秀的逻辑思维与问题解决能力。 - 良好的团队协作与跨部门沟通能力', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:19'), (17, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=e587ad7b-5d66-4519-97af-eab6cd593fec', 'AI研究院-AI算法测试工程师', '科大讯飞', 'd3451680f8119598aa313e64abb436819f5a24aa39bba1dd1c75930c7333f41e', '【工作职责】 职责描述： 1、和研究院算法工程师及研究员一同，保障AI技术产品的先进竞争力及效果质量； 2、聚焦复杂AI解决方案的端到端效果测评工作，主导端到端效果问题的分析、闭环 3、持续跟踪业界竞品动态，结合用户行为数据和专业分析，构建AI产品效果度量标准，推动产品迭代优化； 4、构建端到端测试的效能提升方案，提升测试效率和覆盖性 5、参与需求分析、系统设计、代码评审等环节，从业务场景和技术实现提出改进建议，推动质量问题前移； 【任职资格】 任职要求： 1、计算机相关专业，3年以上软件测试经验，具备大型项目的测试方案设计能力，能够独立负责复杂项目的全流程测试工作。 2、了解常用算法的效果评测指标，能够从用户视角构建端到端效果测试方案 3、有较好的业务理解能力，具备AI算法或者AI解决方案的测试经验优先 4、掌握至少一种编程语言（如Python、Java、C++），具备测试工具开发的能力 5、具备多团队协作、推动能力，能够推动端到端测试中的问题闭环', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (18, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=8966b5c8-a9bf-4fd2-a2b1-fc0096fe66a2', 'AI研究院-中级研究算法工程师', '科大讯飞', '2c085332a84f0788fb029a1ae02e59620d744015f53bdbd58f8aa5fb82d9c708', '【工作职责】 岗位职责： 1. 从事图像处理、OCR或视觉语言多模态大模型的数据构建、模型训练等前沿技术研究与落地； 2. 处理海量数据，创新并优化当前算法，探索新的技术路线； 3. 在解决问题和推动项目进展方面与团队成员密切合作。 【任职资格】 任职要求： 1. 具备硕士以上学位，专业方向在数理统计、计算机科学、信息技术、电子工程或相关领域； 2. 具备图像处理、图像生成、OCR或多模态算法相关经验，对深度学习前沿算法有深刻的认识和理解； 3. 精通至少一种编程语言，如Python、C++等； 4. 能够独立思考和解决问题，具备较强的分析能力和创新能力； 5. 责任心强，具备良好的沟通能力和团队协作精神； 6. 拥有视觉语言多模态研究经验优先。', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (19, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=f172d225-97f6-425a-a2e5-e8dcc0c02aef', 'AI研究院-数据挖掘工程师', '科大讯飞', '2aa15b41e2ef4ea84aad68f6f8ff2397f3f72e9e4de2f472b597fbe16ea81b2c', '【工作职责】 岗位职责： 基于线上回流的用户日志，运用数理知识、分析用户使用偏好、资源需求； 实现并优化文本处理流程，包括数据清洗、分词、词性标注等； 编写高效、可维护的代码，支持后端服务与NLP模型的集成； 配合团队完成项目需求分析和技术实现； 【任职资格】 任职要求： 熟悉Python语言，具备扎实的编程基础； 了解基本的NLP处理知识（例如文本预处理、分词、文本分类等）； 熟悉数据库知识，能够熟练使用SQL或其他数据库查询语言； 具有良好的逻辑思维能力和问题解决能力； 具备较强的团队合作精神和沟通能力；', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (20, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=48ae07ed-d86d-427e-b0bf-648890215a99', 'AI研究院-中级prompt工程师', '科大讯飞', '03cccde3e82ae1037d7790155dbb34831d24e4bfdaa1bc20a8184ca7dde95306', '【工作职责】 1、数据流程优化:与算法团队、产品团队协同搭建通用且高效的数据生产方案，覆盖采集、清洗、标注、质检等环节 2、数据质量管理:参与开发数据质量评估工具，跟进语音交互大模型数据质量的量化评估和方案改进技术方案探索 3、跟踪语音交互/语音识别领域最新技术发展趋势，参与语音数据处理平台的设计与开发 【任职资格】 1、熟练掌握Python等至少一门编程语言，具备良好的代码能力 2、熟悉Linux环境操作及Shell脚本开发 3、具备数据敏感性和逻辑分析能力 4、有语音识别/深度学习/自然语言处理项目经验，有数据工程平台搭建经验。', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (21, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=3d1f88c3-81fb-4daf-a930-ffda76592f04', 'AI研究院-中级AI研发工程师', '科大讯飞', '1de19665041f50a2b6467f4d14414ba940e1d1c6d1c4bcda473162e8fb1d0082', '【工作职责】 1. 负责星辰MaaS系统级研发工作，参与高性能后端系统、基础平台或 AI 基础设施的设计、开发与优化 2. 参与大模型推理与训练系统的工程化落地，包括性能优化、稳定性保障与规模化部署 3. 针对大模型推理场景进行性能分析与加速优化，提升吞吐率、降低延迟和资源成本 4. 参与模型训练、微调及相关工具链的建设与维护，提升训练效率与工程可用性 5. 与算法、平台、产品等团队紧密协作，推动技术方案在实际业务中的落地 6. 参与技术选型、架构设计及核心技术难点攻关，持续改进系统工程质量 【任职资格】 1. 计算机相关专业本科及以上学历，具备扎实的计算机基础（操作系统、计算机网络、数据结构等） 2. 熟练掌握 Go / Python至少一门语言，具备良好的编码习惯和工程能力 3. 具备后端系统研发经验，理解高并发、高可用或分布式系统的基本设计原则 4. 对系统性能优化、资源利用率提升、稳定性建设等方向有实践经验或深入理解', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (22, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=7562d9c2-1705-4214-bae0-8e230af592c1', 'AI研究院-中级AI研发工程师', '科大讯飞', '3df4330ae89968d89f41409895096e15dedbcd880b34770336b13f72aa60a799', '【工作职责】 1. 参与星辰MaaS平台服务端核心子系统的设计、迭代与优化，主导系统概要设计、详细设计工作，独立完成核心模块代码编写与实现； 2. 严格遵循研发规范与流程，负责模块的设计、编码、单元测试全流程落地，同步完成技术设计文档、接口文档等规范编写工作； 3. 独立分析并攻克开发过程中的技术难点与瓶颈问题，快速定位并解决线上及研发阶段的技术故障，保障研发进度与系统稳定性； 4. 跟踪领域前沿技术动态，开展新技术、新框架的调研与验证工作，输出技术调研报告，推动优质技术落地赋能平台迭代。 【任职资格】 1. 具备3年及以上服务端开发实战经验，精通Java技术栈，熟悉Python语言，具备独立完成子系统级设计与编码的能力，有分布式系统开发及落地经验； 2. 技术功底扎实，能结合业务需求完成子系统级架构设计、重构及技术选型，逻辑缜密，可独立分析并解决研发全流程中的复杂技术难题； 3. 具备较强的需求执行能力，能精准理解业务需求并转化为技术方案，高效推进编码、测试、文档编写等全流程工作，确保任务按时保质落地； 4. 可独立阅读英文技术文档，跟进开源技术动态，能规范输出技术设计方案、接口文档等资料，为研发落地提供支撑； 5. 具备高效的需求对接与跨团队协作能力，能主动联动上下游角色推进工作，有主动学习意识，可快速将新技术转化为落地能力并赋能团队。', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (23, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=2b18ef11-94df-4dba-8855-1f4a8e70ee57', 'AI研究院-算法研究员-语音交互NLP', '科大讯飞', 'dd19ee677430152cc6c78a6bc82801025d54e9e23eb0f34cc694bba112e3f3d5', '【工作职责】 1、 负责认知智能及自然语言处理核心算法研究与开发； 2、 负责NLP任务的相关调研、数据分析、模型训练、效果分析优化等工作； 3、 从事公司相关产品和系统中自然语言处理及认知智能功能的效果保障、持续优化； 4、 对接产品、数据标注、测试、开发服务相关上下游人员，保障相关产品研发任务达到预期效果，与相关人员协同完成项目立项、结项、用户体验分析等任务； 【任职资格】 1、硕士及以上学历，计算机、信号处理数学、软件工程、电子与通信、自动化等相关专业，研究生3年以上/博士2年以上NLP研发相关工作经历，具备较为扎实的自然语言处理、人机交互等领域研究或开发经验，对于个别具备较强NLP/NN技术能力的应聘者不受专业限制； 2、 英语六级以上，具备中英文学术论文的调研能力。 3、 具备NLP领域实际项目经验，做为项目的主要负责人员进行过相关产品的研发，对深度学习、自然语言处理、大数据等相关领域的最新进展、模型、算法有深刻理解和实操经验； 4、熟悉Python、C++等编码语言中至少一种，熟悉Linux下的编程开发环境，熟悉数据结构及常见算法。 5、具备深度学习、强化学习、知识图谱方面的研究经验和基础；同时熟悉pytorch等主流深度学习框架，并具备模型训练调参等相关经验； 6、具有良好的沟通能力和团队合作精神，认真负责，较强的逻辑思维能力，沟通能力较强，责任心强，吃苦耐劳，能主动积极地面对工作，具备对AI研发及应用落地产业化的强烈热情；', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (24, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=ebaaf1aa-5e57-4b65-818f-7bef24099732', 'AI研究院-中级AI研发工程师', '科大讯飞', '69a05b9e0d6b4854436fff8d1e1cf599f4ef77ed936c50c1b739e2b98ef24e25', '【工作职责】 1、负责讯飞云平台智能算力基础设施产品的架构设计、开发和维护； 2、参与混合云、弹性调度等基础设施关键技术研究与攻关； 3、优化公有云、专有云、海外云DevOps流程、服务以及工具，保证平台持续稳定高效运转，持续降本增效； 4、负责现网核心业务稳定性保障，参与应急、排障和故障复盘； 【任职资格】 1、本科以上学历，3年以上开发运维经验，熟悉k8s架构、DevOps体系、高可用架构并有实际开发落地经验者优先； 2、熟悉RedHat/CentOS/Ubuntu操作系统原理，TCP/IP以及常用网络协议，具有快速定位和解决问题的能力； 3、至少掌握golang、java、python、c++中的一种开发语言，全栈开发经验者优先； 4、有全球化、混合云开发及应用经验者优先； 5、具备良好的用户服务意识、责任感、团队合作精神以及沟通能力', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (25, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=4e76d6c1-3c79-4736-a1ef-9b3679825abc', 'AI研究院-中级研究算法工程师-评测方向', '科大讯飞', 'ebc110bc207389b4beb2274e6e21fd041a8bff0cc1654b9696613405d97a11b1', '【工作职责】 1.深耕评测与优化的算法工程师，聚焦大语言模型（LLM）、智能体及相关多模态模型的性能评估、能力边界探索及优化方向验证。 2.深度参与前沿大模型及应用的核心评测体系构建，通过强化学习、微调等算法设计创新评测方案，推动模型及应用质量从“可用”向“可靠、可控、可信”进阶，为模型及应用迭代提供关键决策依据。 【任职资格】 1、计算机科学、人工智能、模式识别等相关专业，硕士研究生及以上学历； 2、2年以上算法研发经验，其中至少1年大模型评测或模型优化相关实践经验； 技术栈： 1、精通Python编程，熟练使用PyTorch/TensorFlow等深度学习框架，具备大规模模型训练/推理的工程化经验； 2、深入理解强化学习核心算法（如PPO、DPO、RLHF）与模型微调技术（如LoRA、QLoRA、Prefix Tuning），有实际落地案例（如通过RLHF优化模型对齐人类偏好）； 3、熟悉大模型评测主流方法（如自动指标BLEU/ROUGE/BERTScore、人类评估流程、对抗评测），掌握评测指标设计逻辑与局限性分析； 加分项：有评委模型（Judge Model）相关研究或实践经验（如设计用于评估对话质量的分类/生成式裁判模型、优化裁判模型的一致性/可靠性）；主导或参与过顶会论文（如ACL、EMNLP、NeurIPS）发表，或在Kaggle、GLUE/SuperGLUE等权威评测中取得Top成绩。', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (26, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=154dbf50-dfae-412a-8430-f1bfae42b14c', 'AI研究院-中级AI研发工程师', '科大讯飞', '6a0a0fe9de22e5429702d66cdda6dde9e0e327f92103772e985e8acd37828c5a', '【工作职责】 1、负责讯飞云平台智能算力基础设施产品的架构设计、开发和维护； 2、参与混合云、弹性调度等基础设施关键技术研究与攻关； 3、优化公有云、专有云、海外云DevOps流程、服务以及工具，保证平台持续稳定高效运转，持续降本增效； 4、负责现网核心业务稳定性保障，参与应急、排障和故障复盘； 【任职资格】 1、本科以上学历，3年以上开发运维经验，熟悉k8s架构、DevOps体系、高可用架构并有实际开发落地经验者优先； 2、熟悉RedHat/CentOS/Ubuntu操作系统原理，TCP/IP以及常用网络协议，具有快速定位和解决问题的能力； 3、至少掌握golang、java、python、c++中的一种开发语言，全栈开发经验者优先； 4、有全球化、混合云开发及应用经验者优先； 5、具备良好的用户服务意识、责任感、团队合作精神以及沟通能力', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (27, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=041ac164-05b8-4015-9b83-b18a58c9bad3', 'AI研究院-算法研究员-数字水印', '科大讯飞', '1879dbd979f3d5850113c3ea7430fc6c34aef7c41fee6e3c7a6d43d1b7bda12a', '【工作职责】 1. 参与数字水印算法的研究与实现，开发基于语音、图像、视频和文本方向的数字水印嵌入与提取工具； 2. 优化现有方案性能，提升水印的不可感知性、鲁棒性、高容量和抗干扰能力等； 3. 撰写技术文档，复现前沿论文并参与实验结果分析； 4. 协助团队完成水印技术在版权保护、溯源追踪等场景的落地应用； 【任职资格】 1. 了解数字水印基础算法（如DCT、DWT、LSB等），以及基于深度学习的水印方案等； 2. 计算机科学、信息安全、电子信息、数学、信号处理等相关专业研究生及以上学历，有顶会论文（如IEEE S&P、ACM MM等）撰写、发表经历优先； 3. 计算机基础扎实，具备良好的编码能力，熟练掌握python等编程语言，熟练运用pytorch等开源训练框架； 4. 个性积极、自驱力强、真诚友善，具备较强的人际沟通能力；', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (28, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=ab6f2bc5-3104-488a-bc65-0ec58b52b213', 'AI研究院-中级研究算法工程师-AI安全攻防方向（内容安全和越狱攻击）', '科大讯飞', 'e294047e5a8ff7136510138f38b1bf172c75c1eb1ae0fd801089e8a6bda739a0', '【工作职责】 1、负责AIGC内容安全防护系统的相关算法研究，包括内容风险识别与分类算法； 2、持续优化现有算法模型，提升准确性、效率和鲁棒性，确保算法能够适应不断变化的内容安全需求； 3、参与大规模内容数据的收集、清洗、标注和预处理工作，为算法训练提供高质量的数据集； 4、跟踪国内外内容安全审核领域的最新技术动态和研究成果，引入先进的算法和技术思路，提升团队的技术水平和创新能力； 5、探索新的算法模型和技术手段，以应对复杂多变的内容安全挑战，如深度学习、自然语言处理、计算机视觉等领域的前沿技术。 【任职资格】 1、硕士及以上学历，计算机、电子等相关专业背景； 2、具有2年以上内容安全审核算法研究经验，熟悉常见的审核算法和模型，或具有大模型安全能力研发经验 3、有丰富的机器学习/NLP/CV相关经验，参与相关比赛或发表相关领域会议论文（KDD/WWW/NIPS/ICML/CVPR/ACL/AAAI...） 4、扎实的编程技术，熟悉python/C++ 等编程语言； 5、优秀的分析问题和解决问题的能力，对解决具有挑战性问题充满激情，能够将机器学习算法和业务结合解决现实问题； 6、对技术有热情，有良好的沟通表达能力和团队精神。', '{\"posted_at\": \"2026-05-12T18:40:28\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (29, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=cd86ab8d-680a-4ef8-b826-d76e7332965b', '中级软件开发工程师-JAVA-服务端', '科大讯飞', '26fd449ca76dc94d1d8eedc86c32b7def05ee688614635acbf406fe54d5aa7e3', '【工作职责】 1.参与项目需求评审与工作计划制定； 2.负责产品模块设计开发并编写相关文档 3.研究新兴技术,满足产品需求； 4.负责产品开发中编码与单元测试、缺陷修复 5.负责项目中疑难问题的攻关解决 【任职资格】 1. 计算机相关专业，两年以上JAVA开发经验； 2. JAVA 基础扎实，对 JVM 原理有一定的了解，能够独立排查和解决问题 ； 3. 熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息、spring、ibatis等常见开源框架 ； 4. 熟悉linux常用命令，熟悉 python/shell/javsscript 脚本语言，有sql优化经验； 5. 掌握多线程及高性能的设计与编码及性能调优，有高并发应用开发经验； 6. 具有创新思维，学习能力强，有一定的抗压能力，善于沟通和团队协作，乐于分享； 此岗位为科大讯飞集团统一招聘岗位，人员通过简历筛选、笔试、初试、复试、终审等环节后录用。', '{\"posted_at\": \"2026-05-12T18:39:25\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (30, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=7a77ee2d-c8c7-4fc1-a447-a1529fca68e0', '中级售前咨询经理', '科大讯飞', 'e04898c0d412602c428a0ab1c15dd84a629b1efc1969d44a6299a6aed61bd8aa', '【工作职责】 1、完成产品的售前阶段的客户调研及分析，并结合公司的技术产品，对产品进行客户适应度分析，引导客户对技术和产品的选择； 2、完成应用数据的整理、售前应用方案的编写、讲解以及产品的演示，结合客户实际业务进行售前沟通； 3、负责技术方案、产品说明书等资料的撰写，确保产品技术文档的规范化； 4、跟踪信息化竞争状态，分析市场差异，进行市场和产品定位分析支持。 【任职资格】 1、大学本科以上，计算机相关专业，熟悉python、java、C++其中一种编程语言； 2、相关工作经验，3年以上软件行业售前或咨询工作经验者； 3、具有良好的沟通协调能力、团队合作精神及服务意识； 4、具备的良好逻辑分析能力，思维清晰敏捷，较强的整理能力和归纳总结能力； 5、具有强烈的学习意愿，具备较好的学习能力、问题分析及解决能力； 6、精通Office、具有文档编写能力。', '{\"posted_at\": \"2026-05-12T18:39:25\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (31, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=9d77bf13-4374-4b6a-be6d-d812f2e169d4', '中级交付项目经理', '科大讯飞', '36607be8f4aa78436c41ea4b925c9cb70118ad6a195835c62e28f44739d3bb09', '【工作职责】 1、完成产品的售前阶段的客户调研及分析，并结合公司的技术产品，对产品进行客户适应度分析，引导客户对技术和产品的选择； 2、完成应用数据的整理、售前应用方案的编写、讲解以及产品的演示，结合客户实际业务进行售前沟通； 3、负责技术方案、产品说明书等资料的撰写，确保产品技术文档的规范化； 4、跟踪信息化竞争状态，分析市场差异，进行市场和产品定位分析支持。 【任职资格】 1、大学本科以上，计算机相关专业，熟悉python、java、C++其中一种编程语言； 2、相关工作经验，3年以上软件行业售前或咨询工作经验者； 3、具有良好的沟通协调能力、团队合作精神及服务意识； 4、具备的良好逻辑分析能力，思维清晰敏捷，较强的整理能力和归纳总结能力； 5、具有强烈的学习意愿，具备较好的学习能力、问题分析及解决能力； 6、精通Office、具有文档编写能力。', '{\"posted_at\": \"2026-05-12T18:39:25\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (32, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=458abf3c-5d29-4b8f-9acf-22f89227e27f', '中级高教讲师', '科大讯飞', '4079399dd0b813ebfb9657511c15c0be61475a2672301b4dd97866212c9d6e77', '【工作职责】 岗位职责： 1、负责大数据方向的研发及授课工作； 2、根据教学需要及课程材料，设计上课方式，并完成备课上课； 3、完成课程辅导、竞赛指导工作，解答学生课程疑问，保证学生的学习质量； 4、将产业经验转化为教学资源，设计实验室方案或实训类项目的教学内容。 5、根据公司教学发展方向对课程体系进行研讨修改、课程迭代更新。 6、参与学术交流与研讨、宣讲、培训等，不断提升技术水平和教学能力； 【任职资格】 任职资格： 1、本科及以上学历，计算机相关专业，有3年以上大数据研发经验； 2、对Hadoop中核心组件（HDFS、MapReduce）有深入研究或实践工作应用经验 3、熟悉Spark、Spark SQL、Spark Streaming、Zookeeper、YARN等大数据相关技术和组件； 4、熟练掌握 Hive 及相关ETL工具（包括但不限于：DataX、Flume、Sqoop、Kettle），构建数仓，实现维度建模等操作 5、有大数据离线/实时实际项目开发经验； 6、能熟练使用一种或多种其他语言编程，如：Java/Python； 7、良好沟通技巧、学习能力，具有良好的职业操守； 8、有Docker、Kubernetes容器及编排的实际使用经验优先。', '{\"posted_at\": \"2026-05-12T18:38:02\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (33, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=4be8a50b-512e-42e8-a246-5f56b8a5416e', 'AI Agent工程师', '科大讯飞', 'dbc5066ba04e4acf55d21c53b4674227160ee2e56efb8e3dd023d536b045d536', '【工作职责】 1. 对接各类实际业务，开发AI Agent 系统，并进行持续迭代和优化。 2. 设计与开发能够自主完成复杂任务的 Agent 系统，完成实际业务场景落地，负责 Prompt 编排、Tool 定义与调用、多步骤任务链设计、上下文管理与状态控制等。 3. 根据业务需求构建和优化 RAG 系统，包括数据处理与切分、Embedding 选型、检索优化。 4. 实现 Agent Teams 多智能体协作，包括任务拆解、多 Agent 分工、协调器设计与 Agent 间通信。 5. 建立 Agent 评测体系，通过日志分析和 A/B 测试系统性优化 Agent 效果，降低幻觉率、提升工具调用成功率和复杂任务完成率。 6. 与产品、后端及业务团队紧密协作，能够清晰沟通技术方案与实现边界，推动 Agent 功能从需求到落地的全流程交付 【任职资格】 任职要求 1. 对AI开发工具及框架有深刻的理解，能清晰描述自己的 AI 驱动开发工作流，对 Harness Engineering 有深刻理解。 2. 2 年以上软件开发经验，至少 1 个实际落地的 LLM/Agent 项目经验，熟练掌握 Python，具备良好工程规范意识。 3. 熟悉 RAG 系统构建与调优、Tool Use/Function Calling、Agent Teams 多智能体协作设计。 4. 具备良好的团队协作与沟通能力，能主动推进跨职能协作，适应快速迭代的开发节奏。 5. 对模型微调有经验者优先。 6. 对 AI 技术有强烈好奇心，能快速跟进前沿模型更新并应用到工作中。', '{\"posted_at\": \"2026-05-12T18:38:02\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (34, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=ce3ba5a2-d1f0-429f-8673-429add65b50c', '中级高教讲师-智能物联网讲师', '科大讯飞', '713f5f3fe7435dc87e727e4f7adf9bfdd66a96b2e44ee7381192157a11d3421d', '【工作职责】 1、负责技术方向的教学和项目资源开发工作； 2、根据人工智能课程教学需要及课程材料，设计上课方式，并完成备课和授课任务； 3、完成课程辅导工作，解答学生课程疑问，保证学生的学习质量； 4、根据项目需要，共同完成人培修订、教材共编、项目申报、竞赛支撑等工作； 5、根据公司教学发展方向对课程体系进行研讨修改、课程迭代更新； 6、将产业经验转化为教学资源，设计实验室方案或实训类项目的教学内容； 7、跟进人工智能技术、应用和产业发展，进行新技术和应用的分享和实践； 8、协助配合其他岗位或其他部门完成与本部门有关的工作； 【任职资格】 1、本科及以上学历，研究生学历优先，计算机等相关专业； 2、有本科5年/硕士2年以上人工智能应用实践经验； 3、熟练使用python编程，能基本使用其他一种或多种语言编程，如：Java/C/C++； 4、人工智能算法基础扎实，熟练使用至少一种深度学习框架，如：TensorFlow、PyTorch等； 5、在计算机视觉、自然语言处理、智能语音、图像处理、视频处理和智能推荐等多个领域有至少2个相关的算法研究和项目实践经验； 6、对人工智能新技术发展有较高的敏锐度和觉察力； 7、具备较强的组织、沟通和协调能力，高度的责任心及团队精神； 8、工作主动，诚实守信，热爱教育事业，富有亲和力和爱心，对学生认真负责，具有良好的职业操守； 9、有人工智能落地应用工程经验者优先。', '{\"posted_at\": \"2026-05-12T18:38:02\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:20'), (35, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=75fdabe5-041d-4d49-844e-cec7562433ce', '中级高教讲师-大数据讲师', '科大讯飞', 'a709423fbb8ee5fc8f073bd5adba130fae90c7987a7b15f409a330caaf566c58', '【工作职责】 1、负责大数据教育方向的教学工作； 2、根据教学需要及课程材料，设计上课方式，并完成备课上课； 3、完成课程辅导、竞赛指导工作，解答学生课程疑问，保证学生的学习质量； 4、将产业经验转化为教学资源，设计实验室方案或实训类项目的教学内容。 5、根据公司教学发展方向对课程体系进行研讨修改、课程迭代更新。 6、参与学术交流与研讨、宣讲、培训等，不断提升技术水平和教学能力 【任职资格】 1、本科及以上学历，计算机相关专业，有3年以上大数据行业研发经验； 2、对Hadoop中核心组件（HDFS、MapReduce）有深入研究或实践工作应用经验 ； 3、熟悉Spark、Spark SQL、Spark Streaming、Zookeeper、YARN等大数据相关技术和组件； 4、熟练掌握 Hive 及相关ETL工具（包括但不限于：DataX、Flume、Sqoop、Kettle），构建数仓，实现维度建模等操作； 5、有大数据离线/实时实际项目开发经验； 6、能熟练使用一种或多种其他语言编程，如：Java/Python； 7、良好沟通技巧、学习能力，具有良好的职业操守。', '{\"posted_at\": \"2026-05-12T18:38:02\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (36, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=6db42980-1a24-41d6-859b-cd5b1f70874f', '中级高教讲师-人工智能讲师', '科大讯飞', 'e73c8eae14bc52c4f40afc268e3918a5aa6e1e4d1d61c99963a90439559d38fd', '【工作职责】 1、负责人工智能方向的教学和项目资源开发工作； 2、根据人工智能课程教学需要及课程材料，设计上课方式，并完成备课和授课任务； 3、完成课程辅导工作，解答学生课程疑问，保证学生的学习质量； 4、根据项目需要，共同完成人培修订、教材共编、项目申报、竞赛支撑等工作； 5、根据公司教学发展方向对课程体系进行研讨修改、课程迭代更新； 6、将产业经验转化为教学资源，设计实验室方案或实训类项目的教学内容； 7、跟进人工智能技术、应用和产业发展，进行新技术和应用的分享和实践； 8、协助配合其他岗位或其他部门完成与本部门有关的工作； 【任职资格】 1、本科及以上学历，研究生学历优先，计算机等相关专业； 2、有本科5年/硕士2年以上人工智能应用实践经验； 3、熟练使用python编程，能基本使用其他一种或多种语言编程，如：Java/C/C++； 4、人工智能算法基础扎实，熟练使用至少一种深度学习框架，如：TensorFlow、PyTorch等； 5、在计算机视觉、自然语言处理、智能语音、图像处理、视频处理和智能推荐等多个领域有至少2个相关的算法研究和项目实践经验； 6、对人工智能新技术发展有较高的敏锐度和觉察力； 7、具备较强的组织、沟通和协调能力，高度的责任心及团队精神； 8、工作主动，诚实守信，热爱教育事业，富有亲和力和爱心，对学生认真负责，具有良好的职业操守； 9、有人工智能落地应用工程经验者优先。', '{\"posted_at\": \"2026-05-12T18:38:02\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (37, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=f1bcb861-2a37-4225-a8ea-b84c1cd95dfb', '中级系统测试工程师', '科大讯飞', 'd95ba4db7549121700049de9f1a85d690e16bf7f99d23814f3ec6726630cd20d', '【工作职责】 1. 按照产品架构和业务要求，制定和推进测试策略，测试计划和测试方法 2. 参与产品需求和架构设计评审，保证产品的可测试性 3. 参与测试效果评估和软件质量核查 4. 通过测试相关流程、策略、方法和工具等创新，努力提升测试的质量和效率 5. 解决测试过程中的复杂技术问题 【任职资格】 1. 工科、计算机或其他相关专业本科以上学历 2. 四年以上软件测试、自动化测试或白盒测试工作经验 3. 精通C/C++/java/python等至少一种编程语言 4. 熟悉软件开发和测试流程 5. 具备广泛的技术视野和很强的技术前瞻性，了解测试技术的发展 6. 很强的学习能力、分析能力和解决问题的能力 7. 熟练的文档、沟通表达和辅导技巧 8. 在某一测试领域比如性能、安全、自动化、无线或者数据测试等具备很强的专业技能者优先 9. 熟悉某一业务领域比如大数据，云计算、物联网、移动、软硬一体等的测试方法及测试策略 此岗位为科大讯飞集团统一招聘岗位，人员通过简历筛选、笔试、初试、复试、终审等环节后录用。', '{\"posted_at\": \"2026-05-12T18:37:26\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (38, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=901d5c3f-12fc-4ea0-b448-24d2893cbb10', '中级系统测试工程师', '科大讯飞', '2590ff15a9df50d6944f78b79aa0ac7b3e7890a57b4a2db986182ec95ea7bbad', '【工作职责】 1、参与产品需求分析，制定相关功能点及开发方案，编写测试计划和测试用例‌ 2、执行功能及性能测试，编写测试报告，跟踪问题修复情况，确保产品质量‌ 3、与开发人员、实施人员等各方沟通协作，推动项目顺利进行‌ 4、不断优化测试流程，提升测试效率，定期培训提高团队成员的技术水平‌ 【任职资格】 1、5年以上的相关工作经验‌ 2、需要熟练掌握软件测试基础知识，熟悉测试流程、测试方法和测试工具，如Selenium、JMeter等。 3、需要掌握缺陷跟踪工具如Bugzilla、Jira等，能够编写测试计划、测试用例和测试报告‌ 4、需要熟悉功能测试、性能测试、接口测试、自动化测试等，能够独立编写代码，完成测试脚本‌ 5、Xcode、adb、Jmeter等测试工具，具备Python编程基础，能够基于Python编程开发自动化测试脚本‌ 6、能够参与产品需求分析，制定测试计划，设计和执行测试用例，执行缺陷跟踪和项目质量分析等‌ 8、具备良好的沟通能力、团队协作精神和问题解决能力，能够与开发团队紧密配合，确保软件质量‌', '{\"posted_at\": \"2026-05-12T18:37:26\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (39, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=f356e0a9-0e4d-4437-a6de-a0c985d31cd9', '中级研究算法工程师', '科大讯飞', 'f9b266a9f69b304faf584ff4369930c2aebcf864d61aef4ea17f925f0c2fa148', '【工作职责】 1.主要解决教育场景下各类问题，包括不限于文本版面分析，页面校正，ocr识别，关键点检测、分类等； 2.负责各类图像算法引擎的研究、设计和核心模块实现等工作； 3.负责各类模型的性能优化，以提高模型的准确性和稳定性； 4.配合工程人员开展模型工程化落地工作。 【任职资格】 1.熟练掌握Python，熟悉C++、java等编程语言。 2.熟悉常见的深度学习算法，例如CNN、RNN、Transformer，熟悉常见的深度学习框架如TensorFlow、PyTorch和Keras等；； 3.具有良好的数据处理和分析能力，具备基本的计算机视觉基础知识，如图像处理、特征提取、图像分割等； 4.具有教育场景下深度学习应用相关领域的学术或工程经验者优先考虑； 此岗位为科大讯飞集团统一招聘岗位，人员通过简历筛选、笔试、初试、复试、终审等环节后录用。', '{\"posted_at\": \"2026-05-12T18:37:26\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (40, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=c74d430a-74ad-44d7-8fac-998baca9b018', '高级大数据工程师', '科大讯飞', 'cd6fca9dd6c82ee5d30af55762df7cb929387c61385942b43e015d065688f439', '【工作职责】 1.负责支撑各业务线数据仓库、数据中台、数据中心、数字基座等方案设计、编写工作 2.负责支撑各业务线相关大数据项目的招投标工作，项目验收工作 3.对接客户需求，为客户提供大数据项目的解决方案策划、咨询实施、产品搭建等售前、售中、售后一系列服务或培训服务 4.参与大数据产品架构设计、相关文档评审 5.指导团队数据开发工程师、算法工程师的开发工作 6.参与大数据部分核心技术攻坚工作 【任职资格】 1.5年以上Java、Hadoop开发及管理经验，有传统数仓、数据中台、大数据相关分析产品的开发落地经验 2.有分布式系统分析及架构设计经验，有大型计算集群的基础设施开发维护经验 3.熟悉Java EE相关框架原理，如spring cloud、spring boot、ssh、ssm等 4.熟悉Apache Hadoop平台及相关生态技术，包括MapReduce、HDFS、Spark、Strom、ZooKeeper、HBase、Hive、Flume、Sqoop、Mahout等技术的原理和实施 5.熟悉机器学习常用框架sklearn、tensorflow、keras等 6.熟悉Linux 操作系统和大型关系型数据库MySql、Oracle等，熟悉python、shell、sql、hql等编程语言 7.有大数据项目交付、招投标相关经验优先 8.良好的文档编写能力，学习、沟通能力，富有强烈的责任感和团队意识', '{\"posted_at\": \"2026-05-12T18:37:26\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (41, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=6d35b123-6cae-460f-8338-d1f45cc472ab', '高级运维工程师', '科大讯飞', '797ddbe926931438c8d910897a9009310bc14c544b1ae69ab1d31722744c337d', '【工作职责】 1、负责业务系统及平台部署、运维、扩容、升级。持续对系统进行优化； 2、负责业务系统及平台日常运维管理、服务监控、故障处理、集群性能和资源利用率优化，业务系统常见问题能迅速定位，为开发人员提供技术支持； 3、负责调研前沿技术，改进现有系统的服务和运维架构，提升系统可靠性和可运维性； 【任职资格】 1、本科及以上学历，计算机或者相关专业； 2、3年以上运维岗位经验，精通Linux操作系统； 3、熟悉Nginx、keepalived等开源组件，熟悉如MySQL、Redis、MongoDB、ES等业界主流数据库运维等； 4、需具备一定的shell、python等编程能力，熟悉网络基础知识； 5、熟悉docker、kubernetes，并对此有运维经验； 6、熟悉zabbix、prometheus等常用开源监控工具； 7、有较好的交流沟通能力； 8、对于技术具有浓厚兴趣，具有刻苦学习钻研精神。 此岗位为科大讯飞集团统一招聘岗位，人员通过简历筛选、笔试、初试、复试、终审等环节后录用。', '{\"posted_at\": \"2026-05-12T18:37:26\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (42, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=987884df-d9ce-468e-9ffd-d900913a12a9', '高级系统测试工程师', '科大讯飞', '68e8cae6133f46a7632ce8f008ec3b885b444968dffb900cb1efcd2ba41efdf7', '【工作职责】 1、端到端质量负责，具备系统性的测试方案设计能力和质量评估能力； 2、能独立完成或指导团队成员完成关键测试方案设计与评审，保证方案可靠性； 3、跨部门协作推动专项测试工作开展； 4、具备软件测试技能和软件自动化稳定性测试技能，开展自动化测试、性能稳定性测试、效果测试等专项任务； 【任职资格】 1、有5年及以上的软件测试经验或不低于2年的大屏类产品软硬件测试经验，掌握系统性测试设计方法理论； 2、熟悉windows操作系统相关基础理论知识，开展过驱动健全性测试、系统稳定性（重启、开机、待机等）、故障注入测试等； 3、至少熟练掌握一门开发语言或脚本语言（java或python均可），能够在实际工作中完成PC端专项稳定性测试任务； 4、带领过3人以上的团队，有人员培养经验； 此岗位为科大讯飞集团统一招聘岗位，人员通过简历筛选、笔试、初试、复试、终审等环节后录用。', '{\"posted_at\": \"2026-05-12T18:37:26\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (43, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=ca6f0fb7-33cb-4768-858f-f918b83ad6eb', '高级大数据工程师', '科大讯飞', '3e8cd5adef5a028e795c90136a1844cfb50340813a12daa0ac0e17557f1906b6', '【工作职责】 1.负责支撑各业务线数据仓库、数据中台、数据中心、数字基座等方案设计、编写工作 2.负责支撑各业务线相关大数据项目的招投标工作，项目验收工作 3.对接客户需求，为客户提供大数据项目的解决方案策划、咨询实施、产品搭建等售前、售中、售后一系列服务或培训服务 4.参与大数据产品架构设计、相关文档评审 5.指导团队数据开发工程师、算法工程师的开发工作 6.参与大数据部分核心技术攻坚工作 【任职资格】 1.5年以上Java、Hadoop开发及管理经验，有传统数仓、数据中台、大数据相关分析产品的开发落地经验 2.有分布式系统分析及架构设计经验，有大型计算集群的基础设施开发维护经验 3.熟悉Java EE相关框架原理，如spring cloud、spring boot、ssh、ssm等 4.熟悉Apache Hadoop平台及相关生态技术，包括MapReduce、HDFS、Spark、Strom、ZooKeeper、HBase、Hive、Flume、Sqoop、Mahout等技术的原理和实施 5.熟悉机器学习常用框架sklearn、tensorflow、keras等 6.熟悉Linux 操作系统和大型关系型数据库MySql、Oracle等，熟悉python、shell、sql、hql等编程语言 7.有大数据项目交付、招投标相关经验优先 8.良好的文档编写能力，学习、沟通能力，富有强烈的责任感和团队意识', '{\"posted_at\": \"2026-05-12T18:37:26\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (44, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=9c55c7ef-b5c7-44b8-ba36-527805ac7174', '中级研究算法工程师', '科大讯飞', '3d378b59c33aa5dde620b2e7c1cab39a5a6754c5e45e9965749eaaef4ce52df1', '【工作职责】 1、理解模型研发流程与需求，负责/参与前沿模型研究中数据解决方案的设计、开发和持续维护，探索数据合成算法，充分挖掘人类数据在大模型训练中的价值。 2、开发工具完成数据收集、清洗、格式转换，能够熟练使用各类数据质量清洗、图转文字、音频转文字等工具，优化流程以应对超大规模数据挑战。 3、构建数据自动化评估体系，研究自动化评估算法，能够高效评估无监督、有监督等各类数据质量。 4、追踪业界开源数据进展，清晰了解业界高质量数据构建体系方法，为星火大模型训练数据提供支持。 【任职资格】 1、计算机、软件、通信、自动化、应用数学等相关专业本科以上学历，具备2年以上大数据/算法相关工作经验。 2、熟练使用Python及主流数据科学栈（NumPy、Pandas等），具备良好的代码规范与工程习惯；熟悉SQL及常见关系型/分布式数据库。 3、熟悉主流分布式计算或分析框架（如Spark、Hadoop、Ray、Presto等），理解其核心原理与性能调优方法，能在其上开发或调优数据作业。 4、熟悉主流深度学习框架，并对其训练/微调流程有深刻理解，能清晰分析数据质量对模型性能的影响。', '{\"posted_at\": \"2026-05-12T18:36:16\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (45, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=8041d3e0-5532-4391-a157-3b9aedd415a1', '中级研究算法工程师', '科大讯飞', 'b5f65b049c7d967b0de928328c67efea485cc2603822729fb8d8a9511395ab10', '【工作职责】 1、从事智慧农业领域图像检测和智能监控领域行为检测分析工作； 2、从事图像识别方面的方案设计、数据采集、算法上线等工作； 3、对图像分析具体任务进行性能优化和端上移植； 4、解决图像处理与识别技术在实际应用和产品交付中的问题； 5、相关研发内容的专利转化和交底书撰写。 【任职资格】 1、硕士及以上学历，计算机、信号处理、自动化等相关专业，具备一定的模式识别、图像处理等理论知识； 2、具备较好的PyThon、C++等语言编程能力，有丰富的代码开发经历； 3、熟悉CNN、TransFormer等深度学习算法及其常用框架，对目标检测、语义分割、目标跟踪等图像算法有丰富的研发经验； 4、英语六级及以上，具备中英文文献的调研能力； 5、具备良好的学习能力、分析问题、解决问题的能力，能进行良好的沟通与团队协作； 优先考虑： 1、在CVPR、ICCV、CCF-A等会议或期刊上发表过论文或者拥有相关发明专利；', '{\"posted_at\": \"2026-05-12T18:22:19\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (46, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=d3542147-3c36-462c-aebd-30a4e88a837b', '高级系统架构师', '科大讯飞', '4e3d1064715ddbc345af56eea2e107db278b9b218b446db459d8dbabbcf56e10', '【工作职责】 岗位职责 1、牵头公司云原生技术体系规划与落地，负责 K8s、容器化、服务网格、Serverless 等核心技术栈的架构设计、选型优化与全生命周期管理，搭建高可用、高可扩、低成本的云原生基础设施平台，支撑公司核心业务（AI 大模型、金融投研、分布式服务）的规模化部署与运行； 2、主导云原生平台的性能调优、容灾备份、安全加固体系建设，解决容器编排、资源调度、微服务治理、分布式存储等场景下的核心技术难题，保障平台 99.99% 以上的可用性，支撑亿级用户规模与高并发业务场景； 3、参与公司技术战略制定，结合业务发展（如 AI 大模型推理 / 训练、金融级合规要求）推动云原生技术与业务深度融合，输出云原生最佳实践，赋能各业务线完成从传统架构到云原生架构的迁移与重构，提升研发效率与资源利用率； 4、负责云原生技术团队的技术指导与能力建设，主导技术攻关、方案评审、代码审核，培养团队云原生技术能力，推动团队技术沉淀与创新； 5、跟踪云原生领域前沿技术（如 K8s 新版本、云原生 AI、边缘计算、混沌工程），结合公司业务场景进行技术预研与落地，保持公司云原生技术体系的行业领先性； 6、协同算法、研发、运维、产品等跨部门团队，推动云原生平台与大模型中台、数据中台、业务系统的无缝对接，保障技术方案的落地执行与效果验收。 【任职资格】 核心硬性要求 1、本科及以上学历，计算机、软件工程、通信工程等相关专业，8 年以上云计算 / 云原生相关工作经验，有头部互联网、云计算厂商、金融科技公司云原生平台搭建 / 架构设计经验者优先； 2、精通 Kubernetes/docker 核心原理与实战，熟练掌握 K8s 集群搭建、运维、调优，具备大规模 K8s 集群（500 节点以上）规划、部署与问题排查能力，熟悉 K8s 周边生态（ETCD、Calico、Flannel、Prometheus、Grafana、ELK 等）； 3、精通微服务治理体系，熟练使用 Spring Cloud/Dubbo、Istio/Linkerd、Nacos/Apollo 等框架与工具，具备从 0 到 1 搭建微服务架构并完成云原生改造的实战经验； 4、熟悉云原生存储 / 网络技术，掌握 Ceph、MinIO、Longhorn 等分布式存储方案，具备容器网络规划、优化与故障排查能力，了解云原生安全（容器镜像安全', '{\"posted_at\": \"2026-05-12T18:21:25\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:21'), (47, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=57ea04fd-0053-42b9-ad0b-c74144ab35c7', '高级大数据工程师', '科大讯飞', '89c45ac8ce3b540480c7378d2957c44f8edbd4aa49534add811ce4be2a4e9dd2', '【工作职责】 1.负责支撑各业务线数据仓库、数据中台、数据中心、数字基座等方案设计、编写工作 2.负责支撑各业务线相关大数据项目的招投标工作，项目验收工作 3.对接客户需求，为客户提供大数据项目的解决方案策划、咨询实施、产品搭建等售前、售中、售后一系列服务或培训服务 4.参与大数据产品架构设计、相关文档评审 5.指导团队数据开发工程师、算法工程师的开发工作 6.参与大数据部分核心技术攻坚工作 【任职资格】 1.5年以上Java、Hadoop开发及管理经验，有传统数仓、数据中台、大数据相关分析产品的开发落地经验 2.有分布式系统分析及架构设计经验，有大型计算集群的基础设施开发维护经验 3.熟悉Java EE相关框架原理，如spring cloud、spring boot、ssh、ssm等 4.熟悉Apache Hadoop平台及相关生态技术，包括MapReduce、HDFS、Spark、Strom、ZooKeeper、HBase、Hive、Flume、Sqoop、Mahout等技术的原理和实施 5.熟悉机器学习常用框架sklearn、tensorflow、keras等 6.熟悉Linux 操作系统和大型关系型数据库MySql、Oracle等，熟悉python、shell、sql、hql等编程语言 7.有大数据项目交付、招投标相关经验优先 8.良好的文档编写能力，学习、沟通能力，富有强烈的责任感和团队意识', '{\"posted_at\": \"2026-05-12T18:21:25\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:22'), (48, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=a582272d-f2e9-4357-8aba-d8dc195e22b5', '中级系统测试工程师', '科大讯飞', '625b4e714a4af52d89503e8e9278f9cb93ea1230adeb4abfae9503ef76eb05cd', '【工作职责】 1、负责信创AIPC全产品线的测试工作，负责测试策略制定、用例设计、计划执行及质量保障，确保产品性能、稳定性与兼容性。 2、负责信创AIPC操作系统及生态软件的测试架构与用例设计。制定覆盖产品固件（BIOS/BMC）、OS（Linux/Windows/UOS/Kylin）、驱动、第三方应用及大模型的测试策略，定义信创环境验收标准。测试用例覆盖系统级性能、负载稳定性和软硬件兼容性等。 3、跟随项目开发周期或项目交付导向制定测试计划制定、资源协调与进度管控，保障测试进度和质量。 4、负责测试环境搭建及维护，依据项目要求搭建对应测试环境，依据项目需求进行软硬件测试，输出测试报告满足项目售前、交付阶段各阶段测试需求。 【任职资格】 硬性要求 1、本科及以上学历，计算机/电子工程/自动化相关专业。 2、3年以上操作系统及生态软件测试经验。 3、熟悉PC、工作站硬件架构，熟悉信创OS和通用软件，熟练掌握python/shell/go一种语言可进行自定化测试脚本的编写，熟悉AI测试择优录取。 精通以下至少一个领域： AI硬件测试：昇腾计算卡性能调优、NVLink/HCCS互联协议。 信创生态：国产CPU（鲲鹏/飞腾）、OS、外设兼容性认证。 高可用系统：双机热备、容灾切换、长稳测试方案。', '{\"posted_at\": \"2026-05-12T18:16:44\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:22'), (49, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=4d8763b6-f10f-4c22-9116-895016635939', '中级软件开发工程师-JAVA', '科大讯飞', '34023bc6ff5a7d03aaf619ff015e9eae0b9d7583312bce62434ce8f9388d0362', '【工作职责】 1、负责 JAVA 技术方向的产品和项目研发工作； 2、参与架构设计和实现，根据开发流程进行设计，开发，测试，交付以满足需求； 3、参与项目重点、难点的技术攻坚； 4、参与相关系统文档的撰写和维护； 5、负责对初级工程师进行技术指导和解惑； 6、制定项目研发计划，把控项目研发进度，控制项目质量、进度。 【任职资格】 1、本科及以上学历，计算机或相关专业； 2、5年左右JAVA 开发经验； 3、精通 OO、UML、AOP，熟练掌握 JDBC、JMS、EJB、SSH、Oracle 等，熟悉 ajax，jQuery 等常见技术的使用，熟悉 Java 开发框架，如 SpringMVC、Hibernate 等，熟悉数据库Mysql 的使用，并具有一定优化经验，具有 mongodb 使用经验者优先； 4、有 Tomcat、JBoss,Weblogic、WAS 等开发经验，熟悉 LINUX 操作平台； 5、有承担复杂系统设计相关工作者或者有带团队开发管理工作者优先考虑； 6、思路清晰，思维敏捷，快速的学习能力;善于与他人沟通协作，有强烈的上进心和求知欲。 此岗位为科大讯飞集团统一招聘岗位，人员通过简历筛选、笔试、初试、复试、终审等环节后录用。', '{\"posted_at\": \"2026-05-12T18:39:25\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:22'), (50, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=99dcf072-684b-4c8a-9369-79cd28409be3', 'java开发工程师', '科大讯飞', '990e2dbf0a4c60eb5f8e6c655034faabde8f0b8446258fc893a0a11f4115a0f3', '【工作职责】 1. 参与业务系统的需求分析、架构设计、核心模块开发及技术文档编写； 2. 负责Java后端服务的开发、测试、部署与持续优化，保障系统高性能、高可用与可扩展性； 3. 配合前端、测试、产品等团队协同推进项目落地，参与代码评审与技术问题攻关； 4. 遵循公司研发规范与安全要求，落实代码质量、日志规范、接口安全及数据合规管理。 【任职资格】 1. 本科及以上学历，计算机科学、软件工程或相关专业，具备扎实的Java编程基础和面向对象设计能力； 2. 熟练掌握Spring Boot、MyBatis等主流Java开发框架，熟悉MySQL、Redis、消息队列（如Kafka/RabbitMQ）等常用中间件； 3. 具备良好的系统分析与问题解决能力，有微服务架构、分布式系统或高并发场景开发经验者优先； 4. 熟悉Git、Maven、Linux常用命令及基本运维操作，了解Docker、K8s等容器化技术者加分； 5. 具备良好的沟通协作意识与职业素养，认同团队合作价值观，无任何歧视性限制条件。', '{\"posted_at\": \"2026-05-12T18:39:25\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:22'), (51, '科大讯飞招聘', NULL, 'https://iflytek.zhiye.com/social/detail?jobAdId=0c42693b-802b-4cb3-91aa-cf1c2242540c', '中级高教讲师-JAVA讲师', '科大讯飞', '731cfca199dc1fbf22c1546509e8010ca410fe1df29b679cb4dfa2a204ea8c89', '【工作职责】 岗位职责： 1、负责Java技术方向的实训教学、项目与教学资源研发工作； 2、根据项目需要，参与完成合作院校的人培修订、教材共编、科研申报、竞赛指导、实习就业等相关工作； 3、参与学术交流，关注产业发展，提升个人教学能力与技术水平； 4、协助配合部门安排的其它相关工作。 【任职资格】 任职资格： 1、本科及以上学历，，研究生学历优先，计算机相关专业，本科5年/硕士2年以上应用实践经验； 2、Java基础扎实，理解JVM原理，熟练使用Spring、SpringMVC、SpringBoot、Mybatis等开发框架，以及缓存，中间件，Zookeeper等第三方组件，熟悉Spring Cloud、Kubernates、Docker者优先； 3、具备一定的前端技术能力，包括HTML、CSS、JS、ES6+等，熟悉前端框架Vue、React、Angular者优先； 4、具备良好的表达沟通、团队合作精神，具有一定的组织协调能力。 5、具备持续学习的能力，对行业最新技术、工具和框架有一定的敏感度，能在实际工作中加以了解与使用。', '{\"posted_at\": \"2026-05-12T18:38:02\", \"crawled_at\": \"2026-06-04T08:53:31.442Z\"}', '2026-06-20 18:10:22'), (52, '智联招聘', NULL, 'http://www.zhaopin.com/jobdetail/CCL1480117890J40858643405.htm?refcode=4019&srccode=401901&preactionid=3900666c-409b-43aa-b25a-3de217f774cf', 'C/C++/Java/JS/Python软开（接受应届）', '外企德科数字技术有限公司', 'e22f730ddfccebdd83baf2fa499e7fe8c351a3bee0ce010751d9007dc1415148', 'JavaScript Python C++ Spring MySQL 计算机软件 产业互联网平台 主要地点：（东莞、深圳、杭州、 西安，苏州、上海，武汉，成都，南京、北京）十大研究所，少量（广州、长沙、济南）三个办事处 （1）导师制培训机制，新人入职后半年以上会有导师一对一带教 （2） 部门：ICT(公开，光，计算，无线，数存等 ) 、华为云、2012(中硬，中软，中媒)、消费者BG、BPIT、上海海思、Carbu、数字能源等 （3） 全程线上面试，流程随时跟进可查 一、软件开发工程师 热爱编程，熟悉掌握Java/C++/C/Python/Web开发等编程语言中的一种或多种编程语言，扎实的编程功底 二、算法工程师 1、熟练掌握Java/C/C++/Python其中一个或多个编程语言，有扎实的编程功底；熟悉机器学习、深度学习或图像算法 三、软件测试工程师 1. 热爱编程，熟悉掌握C/C++/Java/Python等编程语言中的一种或多种编程语言，扎实的编程功底 2.有web开发或测试经验、自动化开发或测试经验者优先。 3.熟练掌握系统测试、功能测试、专项测试、软件测试、韧性测试、安全测试方法中的一种或多种方法，有相关测试语言/脚本的编写和实践经验优先 四、数据开发、数据分析岗 薪资福利： 1. 底薪+绩效+项目奖金+年终奖 2. 缴纳五险一金 3.一年数次考评，薪资可上浮 4.带薪年假5-15天，双休', '{\"posted_at\": \"更新于 今天\", \"crawled_at\": \"2026-06-04T13:30:35.414Z\"}', '2026-06-20 18:10:22'), (53, '智联招聘', NULL, 'http://www.zhaopin.com/jobdetail/CC336010610J40851651710.htm?refcode=4019&srccode=401901&preactionid=3900666c-409b-43aa-b25a-3de217f774cf', 'Python开发工程师（实习生）', '四川蜀通信息科技有限公司', '9239e85e2ebb27c8a1dc45cdbfb95b9305377f1940c2485c100e0a624c7e4932', 'Python Flask 人工智能 【岗位职责】 1、根据业务需求，使用Python编写自动化脚本，支撑AI功能的开发与验证； 2、参与AI相关模块的数据预处理、接口调用、结果解析等脚本逻辑实现； 3、配合业务和测试团队，理解需求场景，编写可复用的脚本工具； 4、对已有脚本进行维护、优化和问题排查，保证脚本稳定运行； 5、整理脚本开发过程中的文档和样例，辅助团队沉淀技术资产。 6、服从并有效完成部门领导交代的其它工作事项。 【任职要求】 1、2027届本科在读，计算机、软件工程、人工智能、电子信息等相关专业； 2、熟练掌握Python语法，理解面向对象编程； 3、熟悉至少一种Python Web框架（Flask / FastAPI / Django）； 4、熟悉常用数据结构与算法，能独立完成基础编码任务； 5、熟练使用Git进行代码管理。 6、能够熟练运用D